INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000', 'Gestión de Infraestructura y Logística', '02', 'ACTAS', '02.01', 'Actas Comité de Baja de Bienes', 'P', NULL, 1, 9, NULL, 'CT', 'Agrupación documental que evidencia el retiro definitivo de un bien mueble de sus activos. en cumplimiento de las funciones descritas en la Resolución SENA 089 de 2005. Cumplido el tiempo de retención en el archivo de gestión se transfiere el soporte original al archivo central, en donde una vez agotado el tiempo total, se conserva en forma permanente, por cuanto determina la disposición final de los bienes muebles que formaron parte del patrimonio de la entidad.');
