INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000', 'Gestión de Infraestructura y Logística', '02', 'ACTAS', '02.26', 'Actas de Comité Primario', 'P', NULL, 2, 3, NULL, 'CT', 'Agrupación documental que evidencian la coordinacion y control de las dependencias del Centro de Formación Profesional. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde agotado su tiempo total, se conserva permanentemente por cuanto contiene valores secundarios relacionados con la misión institucional.');
