INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000', 'Gestión de Infraestructura y Logística', '02', 'ACTAS', '02.34', 'Actas de Comité Técnico de Centro', 'P', NULL, 2, 8, NULL, 'CT', 'Agrupación documental que evidencia las decisiones, recomendaciones y evaluaciones de los Centros de Formación Profesional, por su trascendencia para la gestión administrativa, genera valores secundarios. Razón por la cual, cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original archivo central, en donde agotado su tiempo total se conserva permanentemente por cuanto contiene valores secundarios relacionados con la misión institucional.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Citación'), (@id, 2, NULL, 'Agenda'), (@id, 3, NULL, 'Listado de Asistencia'), (@id, 4, NULL, 'Acta');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000', 'Gestión de Infraestructura y Logística', '03', 'ACTOS ADMINISTRATIVOS', '03.02', 'Resoluciones', 'P', NULL, 1, 9, NULL, 'CT,D', 'Agrupación documental que evidencia la expedición de normas, procedimientos o decisiones administrativas que regulan y facilitan el cumplimiento de las actividades misionales y funcionales de la entidad, las cuales se radican y digitalizan en el aplicativo para la gestión documental electrónica OnBase, , a cargo de quien realice la función, cumplido el tiempo de retención en el archivo de gestión, se transfieren el soporte original al archivo central, para su conservación total, por cuanto contiene valores secundarios históricos para la investigación, el soporte digital de las resoluciones se conserva en forma permanente en el aplicativo para la Gestión Electrónica Documental ONBASE, para fines de consulta y protección del soporte físico.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Resolución'), (@id, 2, NULL, 'Acta de Posesión'), (@id, 3, NULL, 'Acta de Notificación'), (@id, 4, NULL, 'Actas Constancia Ejecutoria');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000', 'Relacionamiento Empresarial y Gestión del Cliente', '30', 'DERECHOS DE PETICION', '', '', 'P', NULL, 1, 9, NULL, 'S', 'Los derechos de petición comprenden: las peticiones, quejas, reclamos, sugerencias y felicitaciones que alleguen los ciudadanos por cualquiera de los canales dispuestos para tal fin por la entidad, de conformidad con lo establecido en la Ley 1755, de 2015, Articulo 13 y Resolución 359 de 2016, expedida por el SENA. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde agotado su tiempo total, se realiza una selección cuantitativa aleatoria así: de 10 a 60 unidades del 10%, de 61 a 200 el 5% y de 201 a N el 2% por vigencia, la documentación no seleccionadas serán objeto de eliminación, procedimiento bajo la orientación del Grupo de Administración de Documentos mediante destrucción física por picado, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, articulo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Petición'), (@id, 2, NULL, 'Comunicación de traslado por competencia'), (@id, 3, NULL, 'Respuesta a derecho de petición'), (@id, 4, NULL, 'Informe consolidado de atención a derechos de petición');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000', 'Relacionamiento Empresarial y Gestión del Cliente', '39', 'INFORMES', '39.02', 'Informes a Entes de Control', 'P', NULL, 1, 9, NULL, 'CT', 'Agrupación documental que evidencian el cumplimiento de las funciones institucionales relacionadas con las actividades administrativas, técnicas y misionales, que son requeridos o remitidos periódicamente por la entidad, a los entes de control, como la Contraloría y la Procuraduría. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde agotado el tiempo total, se conserva en forma permanente, por cuanto contiene valores secundarios relacionados con la historia y la misión institucional.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Requerimiento'), (@id, 2, NULL, 'Solicitud de Información'), (@id, 3, NULL, 'Informe Consolidado'), (@id, 4, NULL, 'Respuesta a Requerimiento');
