INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000.4', 'Gestión de Formación Profesional Integral', '57', 'PROGRAMAS', '57.04', 'Programas de Articulación con la Educación Media', 'P', NULL, 2, 8, NULL, 'CT', 'Agrupación documental que evidencian proceso que integra contenidos curriculares, pedagógicos, didácticos y recursos humanos, económicos y de infraestructura de la Educación Media con los de la educación superior, la formación profesional integral y la educación para el trabajo y el desarrollo humano, atendiendo lo establecido en la Ley 119 de 1994 y el Decreto 1860 de 1994. Cumplido el tiempo de retención en archivo de gestión, se trasfiere el soporte original al archivo central, en donde agotado su tiempo total se Conserva permanentemente, por cuanto contiene valores secundarios de tipo histórico, cultural y técnico.');
