INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000.4', 'Gestión de Formación Profesional Integral', '09', 'AUTOEVALUACIÓNES DE PROGRAMAS DE FORMACIÓN', '', '', 'P', NULL, 1, 9, NULL, 'CT', 'Agrupación documental que evidencia el proceso de expedición y renovación de un registro calificado de los diferentes programas de formación impartidos por el SENA, de acuerdo con lo establecido en la Ley 188 de 2008, Decreto 1075 de 2015 y las Resoluciones 663 de 2016 y 3180 de 2017, Cumplido el tiempo de retención en el archivo de gestión se transfiere el soporte original al archivo central, donde agotado el tiempo total, se conserva por cuanto contiene valores secundarios relación con la historia y la misión de la entidad.');
