INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000.4', 'Gestión de Formación Profesional Integral', '63', 'REGISTROS CALIFICADOS DE PROGRAMAS DE FORMACIÓN DE EDUCACIÓN SUPERIOR', '', '', 'P', NULL, 7, 13, NULL, 'CT', 'Agrupación documental que evidencian el trámite de solicitud de otorgamiento, renovación, modificación o ampliación del registro calificado de los programas de educación superior ofertados por el SENA, ante el Ministerio de Educación Nacional a programas académicos de educación superior que cumplen con unas condiciones mínimas de calidad atendiendo lo establecido en la Ley 1188 de 2008 y el Decreto 1075 de 2015. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde agotado su tiempo total, se conserva de forma permanente por cuanto conserva valores secundarios relación con la historia y la misión de la entidad.');
