INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000.4', 'Gestión de Formación', '07', 'APORTES AL SISTEMA GENERAL DE RIESGOS LABORALES DE APRENDICES', '', '', 'P', NULL, 2, 3, NULL, 'E', 'Agrupación documental que evidencian la afiliación de los aprendices al Sistema General de Riesgos Laborales (SGRL); dicha afiliación permite prevenir, proteger y atender a los aprendices de los efectos de las enfermedades y los accidentes que puedan ocurrirles con ocasión o como consecuencia de los trabajos o prácticas que desarrollen. De conformidad con el mandato establecido en el Decreto 055 de 2015, Capitulo 1 Artículo 2°, parágrafo 2. Cumplido el tiempo de retención en el archivo de gestión se transfiere el soporte original al archivo central, en donde agotado su tiempo total se elimina, por cuanto pierde sus valores primarios. El procedimiento de eliminación se realiza bajo la orientación del Grupo de Administración de Documentos mediante destrucción física por picado, atendiendo el procedimiento contenido en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, artículo 2.8.2.2.5');
