INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000.4', 'Gestión de Formación Profesional Integral', '27', 'CONVOCATORIA', '27.02', 'Convocatorias Asignación de Apoyos de Sostenimiento a Aprendices', 'P', NULL, 2, 8, NULL, 'CT', 'Agrupación documental que evidencia la asignación de los apoyos económicos de sostenimiento a los aprendices del SENA, seleccionados por medio de convocatorias, para que cursen su periodo académico mientras se le otorga el contrato de aprendizaje, dirigido a la población vulnerable pertenecientes a los estratos 1 y 2, durante las fases lectiva y práctica conforme a lo establecido en el artículo 41 de la Ley 789 de 2002 y en el Decreto 4690 DE 2005. Cumplido el tiempo de retención en el archivo de gestión se transfiere el soporte original al archivo central, en donde una vez agotado el tiempo total, se conserva en forma permanente por cuanto conserva valores secundarios relacionados con la ciencia, la investigación y la misión institucional.');
