INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000.4', 'Gestión de Formación Profesional Integral', '27', 'CONVOCATORIA', '27.05', 'Convocatorias Asignación de Monitorias Académicas a Aprendices', 'P', NULL, 2, 8, NULL, 'E', 'Agrupación documental que evidencia las estrategias de la Formación Integral para el Trabajo a partir de los ambientes educativos que faciliten el desarrollo del potencial individual y colectivo de los aprendices, de conformidad con lo estipulado en la Resolución 452 de 2014 SENA. Cumplido el tiempo de retención en el archivo de gestión se transfiere el soporte original al archivo central, en donde agotado su tiempo total se elimina por cuanto agotado el valor administrativo carece de valores secundarios, este procedimiento se realiza bajo orientación del Grupo de Administración de Documentos, atendiendo el procedimiento contenido en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
