INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000.4', 'Gestión de Formación Profesional Integral', '57', 'PROGRAMAS', '57.09', 'Programas de Bienestar al Aprendiz', 'P', NULL, 2, 8, NULL, 'CT', 'Agrupación documental que evidencian las estrategias de bienestar institucional dirigidos a los aprendices como miembro de la comunidad educativa, encaminados a la realización de actividades para la identificación y formulación de acciones que atiendan las necesidades psicológicas, físicas y sociales de los aprendices, de conformidad con lo estipulado en la Resolución 452 de 2014. Cumplido el tiempo de retención en el archivo de gestión se transfiere el soporte original al archivo central, en donde agotado su tiempo total, se conservar en forma permanente por cuanto conserva valores secundarios relacionados con la investigación y la misión institucional.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Lineamiento para el Bienestar del Aprendiz'), (@id, 2, NULL, 'Programa de bienestar al aprendiz'), (@id, 3, NULL, 'Evaluación actividades de bienestar'), (@id, 4, NULL, 'Informe de Seguimiento a los programas de bienestar del aprendiz'), (@id, 5, NULL, 'Control de asistencia actividades bienestar al aprendiz'), (@id, 6, NULL, 'Informe de atención servicio de bienestar'), (@id, 7, NULL, 'Soportes ejecución del programa'), (@id, 8, NULL, 'Informe de gestión bienestar al aprendiz EJECUCIÓN DE SERVICIOS COMPLEMENTARIOS');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000.4', 'Gestión de Formación Profesional Integral', '49', 'ORDENES DE SERVICIO PRODUCCIÓN DE CENTROS', '', '', 'P', NULL, 2, 3, NULL, 'E', 'Agrupación documental que evidencian los procesos requeridos para la producción y venta de Bienes y Servicios en los Centros de Formación SENA de conformidad con lo establecido en la Resolución 2486 de 2004 SENA. Cumplido el tiempo de retención en el archivo de gestión se transfiere el soporte original al archivo central, en donde agotado su tiempo total se elimina, La información se consolida en serie boletines, diarios de tesorería del Grupo de Apoyo Administrativo Mixto del área funcional de tesorería. El procedimiento de eliminación está bajo la orientación del Grupo de Administración de Documentos mediante destrucción física por picado, atendiendo el procedimiento contenido en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Solicitud del servicio'), (@id, 2, NULL, 'Cotización'), (@id, 3, NULL, 'Aceptación de la cotización'), (@id, 4, NULL, 'Orden de servicio'), (@id, 5, NULL, 'Autorización de salida de elemento'), (@id, 6, NULL, 'Control de entrega del servicio'), (@id, 7, NULL, 'Cuenta de cobro o factura de venta'), (@id, 8, NULL, 'Evaluación del servicio'), (@id, 9, NULL, 'Reporte de supervisión del trabajo EMPRENDIMIENTO');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000.4', 'Gestión de Emprendimiento y Empresarismo', '51', 'PLANES', '51.06', 'Planes de Asesoría para el Fortalecimiento Empresarial', 'P', NULL, 2, 8, NULL, 'S', 'Subserie que evidencia las actividades que conlleven al mejoramiento de la productividad y competitividad empresarial, a través de una metodología sistemática de fortalecimiento a las Micro y Pequeñas Empresas, de conformidad con lo normado en la Ley 905 de 2004. Cumplido el tiempo de retención en el archivo de gestión se transfiere el soporte original al archivo central, en donde agotado su tiempo total, se realiza una selecciona cuantitativa aleatoria así: de 10 a 60 unidades del 10%, de 61 a 200 el 5% y de 201 a N el 2%, por vigencia, de la producción documental anual, para evidenciar la evolución y fortalecimiento empresarial y la participación del SENA, en el desarrollo económico, social y laboral del país. La documentación no seleccionada será objeto de eliminación, procedimiento bajo la orientación del Grupo Administración de Documentos, mediante destrucción física por picado, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, articulo 2.8.2.2.5.');
