INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000.4', 'Gestión de Emprendimiento y Empresarismo', '39', 'INFORMES', '39.32', 'Informes de Sensibilización de Emprendimiento', 'P', NULL, 1, 4, NULL, 'E', 'Agrupación documental que evidencian las actividades de entrenamiento a través de charlas, seminarios talleres, conferencias teleconferencias y entrenamientos para fortalecer competencias emprendedoras, empresariales y gerenciales de los clientes del SENA. Cumplido el tiempo de retención en el archivo de gestión se transfiere el soporte original al archivo central, en donde agotado su tiempo total se elimina, por cuanto la información se consolida en la serie Programas subserie Programas de Emprendimiento. El proceso de eliminación está bajo la orientación del Grupo Administración de Documentos, mediante destrucción física por picado, atendiendo el procedimiento contenido en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
