INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('10', '00.9000.4', 'Gestión de la Innovación y la Competitividad', '60', 'PROYECTOS', '60.06', 'Proyectos de Investigación, Innovación y Divulgación - SENNOVA', 'P', NULL, 3, 7, NULL, 'CT', 'Agrupación documental que evidencian los estándares de calidad y pertinencia, en las áreas de investigación, desarrollo tecnológico e innovación, de la formación profesional impartida en la Entidad. Atendiendo lo establecido en el artículo 2 literal 1 de la Ley 1286 de 2009. Cumplidos el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, donde agotado su tiempo total, se conserva totalmente por cuanto conserva valores técnicos, científicos y culturales, que sirve como fuente de investigación para futuras investigaciones.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Acta de inicio del proyecto'), (@id, 2, NULL, 'Plan de gestión de'), (@id, 3, NULL, 'Cronograma del proyecto'), (@id, 4, NULL, 'Ficha grupo de investigación'), (@id, 5, NULL, 'Documentos de planeación del proyecto'), (@id, 6, NULL, 'Ficha técnica de la compra'), (@id, 7, NULL, 'Informe de seguimiento técnico'), (@id, 8, NULL, 'Informe de ejecución presupuestal'), (@id, 9, NULL, 'Revisión del marco lógico'), (@id, 10, NULL, 'Artículo para ponencias'), (@id, 11, NULL, 'Patente'), (@id, 12, NULL, 'Registro de marca'), (@id, 13, NULL, 'Escrito de un libro'), (@id, 14, NULL, 'Prototipo'), (@id, 15, NULL, 'Informe final del proyecto'), (@id, 16, NULL, 'Acta de cierre del proyecto');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', NULL, '01', 'ACCIONES CONSTITUCIONALES', '01.03', 'Acciones de Tutela', 'EL', 'IPC', 1, 9, 'El tiempo de retención se inicia a partir de la ejecutoriedad de la sentencia en primera, segunda instancia o la sentencia de la eventual revisión de la Corte Constitucional.', 'S', 'Subserie documental que evidencia la protección los derechos fundamentales que han sido vulnerados a los ciudadanos por acción y omisión de la entidad atendiendo lo establecido en el artículo 86 de la constitución política 1991 y reglamentado por el Decreto 2591 de 1991, Decreto 306 de 1992. y el Capítulo 1. Del Decreto 1069 de 2015 y la Resolución 1-2144 de 2024, Artículo 5. El tiempo de retención se inicia a partir de la ejecutoriedad de la sentencia en primera, segunda instancia o la sentencia de la eventual revisión de la Corte Constitucional. Cumplido el tiempo de retención en el archivo de gestión se transfiere el soporte original al archivo central en donde agotado su tiempo total se realiza una selección cuantitativa aleatoria así: de 10 a 60 unidades del 10%, de 61 a 200 el 5% y de 201 a N el 2% por vigencia, y cualitativa aquellas tutela que implicaron multas y sanciones a la entidad. acciones de tutela que hayan sido objeto de revisión por parte de la Corte Constitucional. Además, seleccionar un porcentaje de aquellas acciones de tutela cuya argumentación jurídica presente casuísticas especiales o legislación particular, relacionada con la misión de la entidad. la muestra obtenida de la selección se conserva permanentemente por cuanto da testimonio para investigación de la Historia Política. Los documentos de archivo no seleccionada se eliminan, de conformidad con lo establecido en el procedimiento de disposición final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, articulo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Escrito de tutela'), (@id, 2, NULL, 'Auto de admisión de tutela y/o traslado'), (@id, 3, NULL, 'Contestación de la tutela'), (@id, 4, NULL, 'Fallo'), (@id, 5, NULL, 'Comunicación de cumplimiento fallo'), (@id, 6, NULL, 'Recurso'), (@id, 7, NULL, 'Comunicación de Incidente de desacato'), (@id, 8, NULL, 'Auto de cierre');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', NULL, '02', 'ACTAS', '02.10', 'Acta de Comité de Contratación', 'EL', 'IPU', 1, 9, 'El tiempo de retención inicia con la última acta suscrita por este comité.', 'CT', 'Subserie documental que evidencia las recomendaciones a los ordenadores del gasto en lo relacionado con las actividades precontractuales, atendiendo lo establecido en la resolución 1-0390 de 2025 art. 5 numeral 5 y art.7. El tiempo de retención inicia con la última acta suscrita por este comité. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde agotado su tiempo total, se conserva por cuanto contienen información que da testimonio de como se pronunciaron los ordenadores del gasto frente a las necesidades de contratación frente al cumplimiento de los objetivos institucionales y los enmarcados en el plan de desarrollo. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas, tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo- SGDEA');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Acta de comité de contratación');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', NULL, '02', 'ACTAS', '02.11', 'Actas de Comité de Convenios', 'EL', 'IPU', 2, 8, 'El tiempo de retención inicia con la última acta suscrita por este comité.', 'CT', 'Subserie documental que evidencia las recomendaciones a los ordenadores del gasto en lo relacionado con las actividades preconvencionales, atendiendo lo establecido en la resolución 1-0390 de 2025 art. 5 numeral 5 y art.7. El tiempo de retención inicia con la última acta suscrita por este comité. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde agotado su tiempo total, se conserva por cuanto contienen información que da testimonio de como se pronunciaron los ordenadores del gasto frente a las necesidades de contratación frente al cumplimiento de los objetivos institucionales y los enmarcados en el plan de desarrollo. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas, tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo- SGDEA');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Acta de comité de convenios');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', NULL, '02', 'ACTAS', '02.30', 'Actas de Comité Primario', 'EL', 'IPC', 1, 9, 'El cierre administrativo de la subserie documental inicia con la última acta de comité primario en la vigencia.', 'CT', 'Subserie documental que evidencia las decisiones referentes a la oferta de formación del centro, basadas en las necesidades del sector productivo, pertinencia y acordes a los planes regionales. El cierre administrativo de la subserie documental inicia con la última acta de comité primario en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva permanentemente, por cuanto evidencia las decisiones y los acuerdos allegados por los miembros del Comité. Para garantizar la preservación a largo plazo de la agrupación, se deben seguir los lineamientos establecidos en los componentes de preservación a largo plazo establecidos por la entidad. Para agilizar la consulta y preservación de la memoria institucional.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Acta de comité primario');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', NULL, '02', 'ACTAS', '02.38', 'Actas de Comité Técnico de Centro', 'EL', 'IPC', 2, 8, 'El tiempo de retención inicia con la última acta de comité técnico de centro expedida en la vigencia.', 'CT', 'Subserie documental que evidencia las decisiones, recomendaciones y evaluaciones de los Centros de Formación Profesional, atendiendo lo establecido en el Decreto 249 de 2004, Artículo 30. El tiempo de retención inicia con la última acta de comité técnico de centro expedida en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva permanentemente, por cuanto evidencia las decisiones y los acuerdos allegados por los miembros del Comité. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo (SGDEA).');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Acta de comité técnico de centro');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', NULL, '02', 'ACTAS', '02.52', 'Actas de Subcomité Centro de formación Institucional de Gestión y Desempeño', 'EL', 'IPC', 2, 8, 'El tiempo de retención a partir de la última acta de subcomité del centro de formación institucional de gestión y desempeño expedida en la vigencia.', 'CT', 'Subserie documental que evidencia las decisiones tomadas por el subcomité, como instancia de seguimiento y control para la implementación y operación del Modelo Integrado de Planeación y Gestión-MIPG, así como de los sistemas de gestión y demás componentes que conforman el Modelo de Operación SIGA en los Centros de Formación, en cumplimiento del Decreto 1083 de 2015 del Departamento de la Función Pública. Decreto 1499 de 2017, artículo 2.2.22. El tiempo de retención a partir de la última acta de subcomité del centro de formación institucional de gestión y desempeño expedida en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto contiene información que da testimonio de las decisiones, acciones y gestión del SENA. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo (SGDEA).');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Acta de subcomité centro de formación institucional de gestión y desempeño');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', NULL, '03', 'ACTOS ADMINISTRATIVOS', '03.02', 'Resoluciones', 'EL', 'IPU', 1, 19, 'El tiempo de retención inicia a partir de la finalización de la vigencia.', 'CT', 'Subserie documental que evidencia la expedición de normas, procedimientos o decisiones administrativas que regulan y facilitan el cumplimiento de las actividades misionales y funcionales. El tiempo de retención inicia a partir de la finalización de la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el original al archivo central, en donde, agotado el tiempo total, se conserva permanentemente, por cuanto ofrece posibilidades investigativas de la evolución y gestión de la entidad. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo (SGDEA).');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Resolución');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'PROCESO GESTIÓN CONTRACTUAL', '22', 'CONTRATOS', '22.01', 'Contratos de Adhesión', 'EL', 'IPU', 1, 19, 'El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas. cumplido el tiempo de retención, en el archivo de gestión se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se realiza una selección cuantitativa aleatoria así: de 1 a 60 unidades, del 10%; de 61 a 200, el 5%; y de 201 a N, el 2%, por vigencia.', 'S', 'Subserie documental que evidencia el acuerdo de voluntades por medio del cual uno de los contratantes, denominado predisponente, impone al otro, llamado adherente, el contenido del contrato sin ninguna posibilidad de discutirlo ni de modificarlo, contando únicamente con la facultad de decidir libremente si contrata o no bajo el clausulado ofrecido, dentro de un esquema de “lo toma o lo deja”, atendiendo lo establecido en la Ley 1150 de 2007. El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas. cumplido el tiempo de retención, en el archivo de gestión se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se realiza una selección cuantitativa aleatoria así: de 1 a 60 unidades, del 10%; de 61 a 200, el 5%; y de 201 a N, el 2%, por vigencia. La muestra obtenida de la selección se conserva permanentemente, por cuanto da testimonio del desarrollo de las actividades administrativas y permite a la entidad aprender de experiencias pasadas y mejorar los procesos de adquisición. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo establecido por la entidad. Los documentos de archivo no seleccionados se eliminan, de conformidad con lo establecido en el procedimiento de disposición final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II, Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
