INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'PROCESO GESTIÓN CONTRACTUAL', '22', 'CONTRATOS', '22.02', 'Contratos de Arrendamiento', 'EL', 'IPU', 1, 19, 'El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas.', 'S', 'Subserie documental que evidencia cronológicamente los documentos generados en el proceso de contratación celebrado entre el SENA con una persona natural o jurídica que cede temporalmente el uso de un bien a cambio de una renta. En el artículo 55 de la Ley 80 de 1993. Atendiendo lo establecido en el art. 25 de la Ley 80 de 1993 y los artículos 50, 51, 52, 53, el literal i) del numeral 4 del artículo 2 de la Ley 1150 de 2007, en concordancia con el artículo 2.2.1.2.1.4.11 del Decreto 1082 de 2015. El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se realiza una selección cuantitativa aleatoria así: de 1 a 60 unidades, del 10%; de 61 a 200, el 5%; y de 201 a N, el 2%, por vigencia. De aquellos contratos que permitieron atender las demandas de los programas de formación a través de ambientes de aprendizaje o de alquiler de equipos que permitieron la ejecución de la formación profesional integral. La muestra obtenida de la selección se conserva permanentemente, por cuanto da testimonio del desarrollo de las actividades administrativas y el compromiso del SENA y otras partes involucradas en la promoción de la educación, además de ser fuente de información de la evolución y el impacto de los programas de formación a lo largo del tiempo. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo establecido por la entidad. Los documentos de archivo no seleccionados se eliminan, de conformidad con lo establecido en el procedimiento de disposición final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II, Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
