INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'PROCESO GESTIÓN CONTRACTUAL', '22', 'CONTRATOS', '22.06', 'Contratos de Fiducia', 'EL', 'IPU', 1, 19, 'El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas.', 'CT', 'Subserie documental que evidencia cronológicamente los documentos generados en el proceso de contratación celebrado entre el SENA y el manejo de recursos con el fin de hacer pagos o desembolsos derivados de un contrato estatal, ya sea por fiducia pública o encargo fiduciario, en concordancia con el artículo 2, numerales 5 y 32, y el artículo 55 de la Ley 1150 de 2007, artículos 32, numeral 4, literal f. El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conservan permanentemente, por cuanto proporcionan un registro histórico de las acciones y decisiones tomadas en relación con la administración de activos para el buen funcionamiento de la administración pública y el uso eficiente de los recursos del Estado en un periodo determinado. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo establecido por la entidad.');
