INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'PROCESO GESTIÓN CONTRACTUAL', '22', 'CONTRATOS', '22.07', 'Contratos de Interventoría', 'EL', 'IPU', 1, 19, 'El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas.', 'CT', 'Subserie documental en la que se conservan de manera cronológica los documentos generados en el proceso de contratación de una persona natural o jurídica para que controle, vigile, inspeccione y verifique a nombre y en representación de una entidad estatal el cumplimiento de una, varias o todas las obligaciones derivadas de un contrato. Atendiendo lo establecido en el artículo 55 de la Ley 80 de 1993 y el artículo 83 de la Ley 1474 de 2011. El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva cuanto proporciona para realizar investigaciones sobre la coordinación y control de la contratación que desarrolla la entidad en cumplimiento de un proyecto especializado. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo establecido por la entidad.');
