INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'PROCESO GESTIÓN CONTRACTUAL', '22', 'CONTRATOS', '22.08', 'Contratos de Licenciamiento', 'EL', 'IPU', 1, 19, 'El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas, Cumplido el tiempo de retención, en el archivo de gestión se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva permanentemente, por cuanto proporciona información que permite la renovación o actualización de las licencias.', 'CT', 'Subserie documental que evidencia cronológicamente los documentos generados en el proceso de contratación celebrado entre el SENA y personas naturales y jurídicas para el soporte técnico, mantenimiento y renovación de licenciamiento de plataformas, en concordancia con lo establecido en la Ley 80 de 1993 y la Ley 1150 de 2007. El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas, Cumplido el tiempo de retención, en el archivo de gestión se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva permanentemente, por cuanto proporciona información que permite la renovación o actualización de las licencias. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo establecido por la entidad.');
