INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'PROCESO GESTIÓN CONTRACTUAL', '22', 'CONTRATOS', '22.09', 'Contratos de Prestación de Servicios', 'EL', 'IPU', 1, 19, 'El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas.', 'S', 'Subserie documental en la que se conservan de manera cronológica los documentos generados en el proceso de contratación celebrado por las entidades estatales con personas naturales o jurídicas con el objeto de realizar actividades relacionadas con la administración o funcionamiento de una entidad pública. Artículo 32 de la Ley 80 de 1993. El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se realiza un muestreo aleatorio simple, teniendo en cuenta el criterio de unidades documentales definido: de 1 a 60 unidades, del 10%; de 61 a 200, el 5%; y de 201 a N, el 2%, por vigencia. La muestra obtenida de la selección se conserva permanentemente por cuanto da testimonio de la gestión de contratación en el marco de las líneas de negocios con sus clientes. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo establecido por la entidad. Los documentos de archivo no seleccionados se eliminan, de conformidad con lo establecido en el procedimiento de disposición final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II, Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
