INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'GESTIÓN DEL TALENTO HUMANO', '22', 'CONTRATOS', '22.10', 'Contratos de Prestación de Servicios Personales', 'EL', 'IPU', 1, 19, 'El tiempo de retención inicia a partir de la finalización del amparo de las pólizas de cumplimiento.', 'S', 'Subserie documental que evidencia el orden cronológico de los documentos de archivo generados en el proceso de contratación celebrado por el SENA. En cumplimiento de los art 209 Constitución Política de 1991, la Ley 80 de 1993 articulo 32 numeral 3. Ley 1150 de 2007. El tiempo de retención inicia a partir de la finalización del amparo de las pólizas de cumplimiento. Cumplido el tiempo de retención en archivo de gestión se trasfiere el soporte original al archivo central en donde agotado su tiempo total se realiza una selección cuantitativa aleatoria así: de 1 a 60 unidades del 10%, de 61 a 200 el 5% y de 201 a N el 2%, por vigencia, la muestra obtenida de la selección se conserva permanentemente por cuanto da testimonio del desarrollo de las actividades administrativas y/o como fuente de interés para la entidad o para investigación futuras. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan preservación a largo plazo establecido por la entidad. Los documentos de archivo no seleccionada se eliminan, de conformidad con lo establecido en el procedimiento de disposición final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, articulo 2.8.2.2.5.');
