INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'PROCESO GESTIÓN CONTRACTUAL', '22', 'CONTRATOS', '22.12', 'Contratos de Seguros', 'EL', 'IPU', 1, 19, 'El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas.', 'CT', 'Subserie documental en la que se conservan de manera cronológica los documentos generados en el proceso de contratación celebrado por las entidades estatales con una persona natural o jurídica en el que se trasladan los riesgos al asegurador a cambio de una remuneración. Atendiendo lo establecido en la Ley 80 de 1993, artículo 55. El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conservan permanentemente, por cuanto proporcionan información sobre las pólizas de seguro, las coberturas, los límites y las condiciones, lo que es fundamental para evaluar y gestionar adecuadamente los riesgos asociados con los activos y las operaciones de la entidad. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo establecido por la entidad.');
