INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'PROCESO GESTIÓN CONTRACTUAL', '22', 'CONTRATOS', '22.13', 'Contratos de Suministros', 'EL', 'IPU', 1, 19, 'El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas.', 'S', 'Subserie documental en la que se conservan de manera cronológica los documentos generados en el proceso de contratación celebrado entre SENA y personas naturales o jurídicas, en el cual una parte se obliga, a cambio de una contraprestación, a cumplir en favor de otra, en forma independiente, prestaciones periódicas o continuadas de cosas o servicios. Atendiendo lo establecido en la Ley 80 de 1993, el artículo 968 del Decreto 410 de 1971. El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se realiza un muestreo sistemático aleatorio, teniendo en cuenta el criterio de unidades documentales definidas: del 10% de 1 a 60 unidades, del 5% de 61 a 200 y del 2% de 201 a N, por vigencia. La muestra obtenida de la selección se conserva permanentemente, por cuanto da testimonio del desarrollo de las actividades administrativas y permite a la entidad aprender de experiencias pasadas y mejorar los procesos de adquisición. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo establecido por la entidad. Los documentos de archivo no seleccionados se eliminan, de conformidad con lo establecido en el procedimiento de disposición final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II, Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
