INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'RELACIONAMIENTO CON LA CIUDADANÍA, LA EMPRESA Y ACTORES INTERNACIONALES', '25', 'CONVENIOS', '25.01', 'Convenios de Ampliación de Cobertura', 'EL', 'IPU', 1, 19, 'Los tiempos de retención inician a partir de cierre administrativo o legalización del acta de liquidación.', 'S', 'Subserie documental que evidencia la celebración de alianzas con instituciones o entidades públicas y privadas inscritas en el Banco de Instituciones Educativas o entidades (BIE-SENA) como respuesta estratégica para atender un mayor número de colombianos con formación en programas técnicos, tecnólogos y formación complementaria. Atendiendo lo establecido en los artículos 32 y 40 de la ley 80 de 1993, y el numeral 18 de los artículos 3 y 4 del Decreto 249 de 2004 y el Decreto 092 de 2017. Los tiempos de retención inician a partir de cierre administrativo o legalización del acta de liquidación. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se realiza una selección cuantitativa así: de 1 a 60 unidades, del 10%; de 61 a 200, el 5%; y de 201 a N, el 2%, por vigencia, de aquellos convenios que por su objeto contractual han permitido el desarrollo de la ciencia, innovación y tecnología. La muestra obtenida de la selección se conserva permanentemente, por cuanto da testimonio del desarrollo de las actividades administrativas y/o como fuente de interés para la entidad o de investigación futura. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo (SGDEA). Los documentos de archivo no seleccionados se eliminan, de conformidad con lo establecido en el procedimiento de disposición final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II, Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
