INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'RELACIONAMIENTO CON LA CIUDADANÍA, LA EMPRESA Y ACTORES', '25', 'CONVENIOS', '25.02', 'Convenios de Asociación', 'EL', 'IPU', 1, 19, 'El tiempo de retención inicia a partir de la finalización del amparo de las pólizas.', 'S', 'Subserie documental que evidencia la celebración de convenios con entidades privadas sin ánimo de lucro y de reconocida idoneidad para impulsar programas y actividades acordes con el Plan Nacional de Desarrollo y los Planes Seccionales de Desarrollo. Atendiendo lo establecido en los artículos 209 y 355 de la Constitución política de Colombia, Art. 96 de la Ley 489 de 1998 y el Decreto 092 de 2017. El tiempo de retención inicia a partir de la finalización del amparo de las pólizas. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se realiza una selección cuantitativa aleatoria así: de 1 a 60 unidades, del 10%; de 61 a 200, el 5%; y de 201 a N, el 2%, por vigencia. La muestra obtenida de la selección se conserva permanentemente, por cuanto da testimonio del desarrollo de las actividades administrativas y/o como fuente de interés para la entidad o para investigaciones futuras. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo establecido por la entidad. Los documentos de archivo no seleccionados se eliminan, de conformidad con lo establecido en el procedimiento de disposición final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II, Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
