INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'RELACIONAMIENTO CON LA CIUDADANÍA, LA EMPRESA Y ACTORES INTERNACIONALES', '25', 'CONVENIOS', '25.07', 'Convenios Interadministrativos', 'EL', 'IPU', 1, 19, 'El tiempo de retención inicia a partir de la suscripción del acta de liquidación.', 'CT', 'Subserie documental que evidencia la relación interadministrativa entre dos entidades públicas con el fin de coordinar, cooperar, colaborar o distribuir competencias en la ejecución de funciones administrativas de interés común. En cumplimiento de lo establecido en el art. 2.2.1.2.1.4.1 del Decreto 1082 de 2015, ley 1474 de 2011. El tiempo de retención inicia a partir de la suscripción del acta de liquidación. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto proporciona información que permitió la ejecución de las funciones administrativas de interés común en un periodo determinado. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo por la entidad, con el fin de atender la consulta y la conformación de la memoria institucional.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Solicitud radicada'), (@id, 2, NULL, 'Estudios previos'), (@id, 3, NULL, 'Acto administrativo de justificación de contratación directa'), (@id, 4, NULL, 'Plan de adquisiciones'), (@id, 5, NULL, 'Concepto técnico de viabilidad'), (@id, 6, NULL, 'Certificado de disponibilidad presupuestal - CDP'), (@id, 7, NULL, 'Acta de aprobación del comité de contratación y convenios'), (@id, 8, NULL, 'Norma de creación para entidades públicas'), (@id, 9, NULL, 'Comunicación de manifestación de interés'), (@id, 10, NULL, 'Copia del RUT o número de identificación tributaria'), (@id, 11, NULL, 'Copia de la resolución de nombramiento y acta de posesión del representante legal'), (@id, 12, NULL, 'Copia del documento de identificación del representante legal'), (@id, 13, NULL, 'Certificación de contrapartida, expedida por el representante legal o el revisor fiscal'), (@id, 14, NULL, 'Autorización expresa para firmar el convenio'), (@id, 15, NULL, 'Declaración de no estar inmerso en las prohibiciones, inhabilidades e incompatibilidades, o conflictos de interés'), (@id, 16, NULL, 'Certificado de antecedentes fiscales'), (@id, 17, NULL, 'Certificado de antecedentes disciplinarios'), (@id, 18, NULL, 'Certificado de antecedentes penales'), (@id, 19, NULL, 'Consulta de no estar vinculado como infractor de la ley 1801 de 2016'), (@id, 20, NULL, 'Certificación de los pagos al sistema de seguridad social integral (salud, pensiones, riesgos laborales) y cuota de aprendizaje'), (@id, 21, NULL, 'Certificado de titularidad y vigencia de la cuenta bancaria'), (@id, 22, NULL, 'Acta de aprobación del comité de contratación y convenios'), (@id, 23, NULL, 'Acto administrativo de justificación de contratación directa'), (@id, 24, NULL, 'Designación de supervisor'), (@id, 25, NULL, 'Designación miembros del comité coordinador'), (@id, 26, NULL, 'Acta de inicio del convenio'), (@id, 27, NULL, 'Plan operativo'), (@id, 28, NULL, 'Comunicación producida en la ejecución del convenio'), (@id, 29, NULL, 'Informes de ejecución de la formación profesional'), (@id, 30, NULL, 'Documento e informes supervisión'), (@id, 31, NULL, 'Actas del comité coordinador'), (@id, 32, NULL, 'Informes del conveniente'), (@id, 33, NULL, 'Acta de liquidación del convenio'), (@id, 34, NULL, 'Resolución de liquidación unilateral del convenio'), (@id, 35, NULL, 'Notificación'), (@id, 36, NULL, 'Solicitud de publicación acta de liquidación en secop'), (@id, 37, NULL, 'Constancia de publicación en SECOP II');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'RELACIONAMIENTO CON LA CIUDADANÍA, LA EMPRESA Y ACTORES INTERNACIONALES', '27', 'DERECHOS DE PETICIÓN', '', '', 'EL', 'IPU', 1, 9, 'El tiempo de retención inicia con la respuesta del último derecho de petición recibido en la vigencia.', 'S', 'Serie documental que evidencia los derechos de petición que interponen los ciudadanos por cualquiera de los canales de atención dispuestos por la entidad para tal fin. En cumplimiento del artículo 23 de la Constitución Política de Colombia, Ley 1437 de 2011, Ley 1712 de 2014, Ley 1755 de 2015, Resolución 01365 de 2022 SENA y normas y/o actos administrativos que modifiquen adicionen o sustituyan. El tiempo de retención inicia con la respuesta del último derecho de petición recibido en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde agotado su tiempo total, se realiza un muestreo aleatorio así: de 1 a 60 unidades del 10%, de 61 a 200 el 5% y de 201 a N el 2%, por vigencia. La muestra obtenida de la selección se conserva permanentemente por cuanto da testimonio de la gestión institucional en el marco de los derechos de petición tramitado en un determinado tiempo para la historia de la entidad. Para garantizar la disponibilidad y acceso a la información de esta agrupación documental la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan preservación a largo plazo por la entidad, con el fin de atender la consulta y la conformación de la memoria institucional. Los documentos de archivo no seleccionados se eliminan, de conformidad con lo establecido en el procedimiento de disposición final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, articulo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Derecho de petición'), (@id, 2, NULL, 'Respuesta a derecho de petición');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'RELACIONAMIENTO CON LA CIUDADANÍA, LA EMPRESA Y ACTORES INTERNACIONALES', '42', 'INFORMES', '42.01', 'Informes a Entes de Control', 'EL', 'IPU', 1, 9, 'El tiempo de retención inicia a partir de la entrega del Informe al interesado en la vigencia.', 'CT', 'Subserie documental que evidencia las respuestas dadas por el SENA a los requerimientos solicitados por diferentes entes de control como la Contraloría, la Procuraduría, entre otros, en cumplimiento con la Ley 1121 de 2006. Ley 1712 DE 2014. Estatuto Orgánico del Sistema Financiero, artículos 102 al 105. El tiempo de retención inicia a partir de la entrega del Informe al interesado en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, donde, agotado el tiempo total, se conserva permanentemente como evidencia de las acciones realizadas por la entidad. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo (SGDEA).');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Solicitud de informe por Entes de Control y Vigilancia'), (@id, 2, NULL, 'Informe');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'RELACIONAMIENTO CON LA CIUDADANÍA, LA EMPRESA Y ACTORES INTERNACIONALES', '42', 'INFORMES', '42.02', 'Informe a Entidades del Estado', 'EL', 'IPU', 1, 9, 'El tiempo de retención inicia a partir de la entrega del Informe al interesado en la vigencia.', 'CT', 'Subserie documental que evidencia las respuestas a los requerimientos presentados a las entidades del Estado en conformidad con las funciones asignadas en el artículo 27, numeral 33 del Decreto 249 de 2004. El tiempo de retención inicia a partir de la entrega del Informe al interesado en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva como evidencia de las relaciones interestatales en cumplimiento de su misión y de sus funciones administrativas. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo (SGDEA).');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Requerimiento'), (@id, 2, NULL, 'Informe');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'RELACIONAMIENTO CON LA CIUDADANÍA, LA EMPRESA Y ACTORES INTERNACIONALES', '42', 'INFORMES', '42.29', 'Informes de Gestión', 'EL', 'IPU', 1, 4, 'El tiempo de retención inicia con el último informe de gestión en la vigencia.', 'E', 'Subserie documental que permite la consolidación de la información general, donde se da cuenta de los logros, metas y procesos de la gestión en un período determinado. El tiempo de retención inicia con el último informe de gestión en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, donde, agotado su tiempo total, se elimina, por cuanto la información se consolida en la serie Informes, subserie Informes de Gestión Anual Institucional, en la Dirección de Planeación y Direccionamiento Corporativo. La eliminación se realiza atendiendo lo establecido en el procedimiento de Disposición Final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II, Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Informes de gestión'), (@id, 2, NULL, 'Comunicación de Remisión del informe consolidado a la Dirección de Planeación y Direccionamiento Corporativo');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'GESTIÓN DOCUMENTAL', '44', 'INSTRUMENTOS DE CONTROL', '44.01', 'Instrumentos de Control de Entrega de Comunicaciones Oficiales', 'P', 'IPU', 1, 4, 'El tiempo de retención Inicia con la ultima planilla de entrega realizada en la vigencia.', 'E', 'Subserie documental que evidencia el registro, control y distribución interna de las comunicaciones oficiales en la unidad administrativa responsable del trámite. En cumplimiento de la Ley 594 de 2000. Acuerdo 60 de 2001 AGN. El tiempo de retención Inicia con la ultima planilla de entrega realizada en la vigencia. Una vez cumpla el tiempo de retención en el archivo de gestión se transfiere al archivo central en donde agotado su tiempo total se elimina por cuanto información esta en la serie o subserie respectiva por los cuales se dio el tramite. La eliminación se realiza atendiendo lo establecido en el procedimiento de Disposición Final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, articulo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Planillas de entrega de comunicaciones oficiales internas'), (@id, 2, NULL, 'Planillas de entrega de comunicaciones oficiales producidas para el medio externo');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'GESTIÓN CONTRACTUAL', '52', 'ORDENES DE COMPRA', '', '', 'EL', 'IPU', 1, 19, 'El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas.', 'S', 'Serie documental que evidencia cronológicamente los documentos generados en el proceso de contratación celebrado por la SENA con una persona natural o jurídica para adquirir bienes o servicios que requieran para el cumplimiento de su misión en la tienda virtual del Estado colombiano. Atendiendo lo establecido en la Ley 80 de 1993 y la Ley 1150 de 2007. El tiempo de retención inicia a partir de la finalización de la vigencia del amparo de las pólizas. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se realiza una selección cuantitativa aleatoria así: de 1 a 60 unidades, del 10%; de 61 a 200, el 5%; y de 201 a N, el 2%, por vigencia. La muestra obtenida de la selección se conserva permanentemente como evidencia de la gestión administrativa que permitió el cumplimiento de la misión en un periodo determinado. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo establecido por la entidad. Los documentos de archivo no seleccionados se eliminan, de conformidad con lo establecido en el procedimiento de disposición final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Comunicación solicitud orden de compra'), (@id, 2, NULL, 'Instrumento de agregación de demanda'), (@id, 3, NULL, 'Certificado de disponibilidad presupuestal - CDP'), (@id, 4, NULL, 'Estudios previos'), (@id, 5, NULL, 'Simulador instrumento de agregación de demanda - IAD'), (@id, 6, NULL, 'Constancia de selección proveedor'), (@id, 7, NULL, 'Orden de compra'), (@id, 8, NULL, 'Certificado de registro en la plataforma BlackBox'), (@id, 9, NULL, 'Certificado de registro presupuestal - PR'), (@id, 10, NULL, 'Factura de orden de compra'), (@id, 11, NULL, 'Informe de seguimiento a orden de compra'), (@id, 12, NULL, 'Modificaciones/ adición/ cancelación orden de compra'), (@id, 13, NULL, 'Certificado de publicación SECOP II');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'GESTIÓN CONTRACTUAL', '79', 'PROCESOS DE RESPONSABILIDAD FÍSCAL', '', '', 'EL', 'IPU', 1, 9, 'El tiempo de retención inicia una vez se haya surtido la finalización del trámite administrativo de responsabilidad fiscal, en concordancia con lo establecido en el Acuerdo No. 02 de 2014, artículo No. 10.', 'E', 'Serie documental que evidencia la gestión adelantada por la Dirección Administrativa y Financiera para recuperar bienes de propiedad y en custodia de personas que ya no tienen vinculación con el SENA (exfuncionarios, pensionados, excontratistas y fallecidos) y aquellos que se reportan como faltantes a cargo de algún cuentadante, de conformidad con lo establecido en la Ley 962 de 2005, Artículo 28, y la Resolución No. 1378 de 2018 y el Art. 15, numeral 2 del Decreto 249 de 2004. El tiempo de retención inicia una vez se haya surtido la finalización del trámite administrativo de responsabilidad fiscal, en concordancia con lo establecido en el Acuerdo No. 02 de 2014, artículo No. 10. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, donde, agotado el tiempo total, se elimina por cuanto pierde sus valores primarios y la información se encuentra registrada en las actas de baja por cuenta de responsabilidad. La eliminación se realiza atendiendo lo establecido en el procedimiento de Disposición Final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II, Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Denuncia de perdida'), (@id, 2, NULL, 'Informe al ordenador del gasto'), (@id, 3, NULL, 'Designación de investigador administrativo'), (@id, 4, NULL, 'Notificación al asegurador'), (@id, 5, NULL, 'Informe del asegurador'), (@id, 6, NULL, 'Reposición o pago del bien'), (@id, 7, NULL, 'Evidencia y soporte de investigación'), (@id, 8, NULL, 'Informe resultado de investigación'), (@id, 9, NULL, 'Acta de baja de bien'), (@id, 10, NULL, 'Orden de archivo del expediente'), (@id, 11, NULL, 'Remisión a Control Interno y/o ente de control');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'GESTIÓN CONTRACTUAL', '64', 'PROCESOS CONTRACTAULES DECLARADOS DESIERTOS', '', '', 'EL', 'IPU', 1, 19, 'El tiempo de retención inicia a partir de que quede en firme la resolución por la cual se declara desierto el proceso, y, cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se eliminan toda vez que la información queda consignada en la resolución por la cual se declara desierto el proceso contractual.', 'E', 'Serie documental que evidencia cronológicamente los documentos generados en el proceso contractual que se declara desierto o no adjudicado, atendiendo lo establecido en la Ley 80 de 1993, artículo 55, y el artículo 2.2.3.1.3.5 - 2.2.4.2.2.4.5 del Decreto 1082 de 2015. El tiempo de retención inicia a partir de que quede en firme la resolución por la cual se declara desierto el proceso, y, cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se eliminan toda vez que la información queda consignada en la resolución por la cual se declara desierto el proceso contractual. El procedimiento de disposición final de eliminación a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces, se realiza mediante destrucción física por picado, atendiendo el procedimiento contenido en el Decreto 1080 de 2015, CAPÍTULO II, Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Documentos precontractuales'), (@id, 2, NULL, 'Resolución por la cual se declara desierto el proceso contractual'), (@id, 3, NULL, 'Comunicación de declaración de desierto del procesos'), (@id, 4, NULL, 'Publicación del acto administrativo en portal Web institucional');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000', 'GESTIÓN CONTRACTUAL', '65', 'PROCESOS CONTRACTUALES REVOCADOS', '', '', 'EL', 'IPU', 1, 19, 'El tiempo de retención inicia a partir de que quede en firme la resolución por la cual se declara revocado el proceso.', 'E', 'Serie documental que evidencia cronológicamente los documentos generados en el proceso contractual que se declaran revocados, atendiendo lo establecido en el artículo 93 de la Ley 1437 de 2011 y el artículo 2.2.1.1.2.1.5 del Decreto 1082 de 2015, atendiendo lo establecido en la Ley 80 de 1993, artículo 55, y el artículo 2.2.3.1.3.5 - 2.2.4.2.2.4.5 del Decreto 1082 de 2015. El tiempo de retención inicia a partir de que quede en firme la resolución por la cual se declara revocado el proceso. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se eliminan toda vez que la información queda consignada en la resolución por la cual se declara revocado el proceso contractual. El procedimiento de disposición final de eliminación a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces se realiza mediante destrucción física por picado, atendiendo el procedimiento contenido en el Decreto 1080 de 2015, CAPÍTULO II, Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Documentos precontractuales'), (@id, 2, NULL, 'Resolución por la cual se declara revocado el proceso'), (@id, 3, NULL, 'Comunicación de declaración de revocatoria del proceso'), (@id, 4, NULL, 'Publicación del acto administrativo en portal Web institucional');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.2', 'GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '07', 'BANCO DE INSTRUMENTOS DE EVALUACIÓN DE ASPIRANTES A PROGRAMAS DE FORMACIÓN', '', '', 'EL', 'IPC', 2, 8, 'El tiempo de retención inicia con el consolidado de resultados en la vigencia.', 'E', 'Serie documental que evidencia los instrumentos de evaluación diseñados para medir las habilidades, conocimientos y aptitudes de los aspirantes en áreas específicas relacionadas con los programas de estudio ofrecidos por el SENA. El tiempo de retención inicia con el consolidado de resultados en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se eliminan, por cuanto su información no contiene datos históricos e investigativos. Los documentos de archivo no seleccionados se eliminan, de conformidad con lo establecido en el procedimiento de disposición final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Lista verificación perfil de ingreso'), (@id, 2, NULL, 'Perfiles de ingreso'), (@id, 3, NULL, 'Evaluación diagnóstica de Ítems'), (@id, 4, NULL, 'Plan de diseño Ítems'), (@id, 5, NULL, 'Acuerdo confidencialidad del diseñador'), (@id, 6, NULL, 'Lista de chequeo Ítems'), (@id, 7, NULL, 'Solicitud pruebas'), (@id, 8, NULL, 'Registro de resultados taller actitudinal'), (@id, 9, NULL, 'Taller actitudinal'), (@id, 10, NULL, 'Consolidado de resultados');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.2', 'RELACIONAMIENTO CON LA CIUDADANÍA, LA EMPRESA Y ACTORES INTERNACIONALES', '27', 'DERECHOS DE PETICIÓN', '', '', 'EL', 'IPU', 1, 9, 'El tiempo de retención inicia con la respuesta del último derecho de petición recibido en la vigencia.', 'S', 'Serie documental que evidencia los derechos de petición que interponen los ciudadanos por cualquiera de los canales de atención dispuestos por la entidad para tal fin. En cumplimiento del artículo 23 de la Constitución Política de Colombia, Ley 1437 de 2011, Ley 1712 de 2014, Ley 1755 de 2015, Resolución 01365 de 2022 SENA y normas y/o actos administrativos que modifiquen adicionen o sustituyan. El tiempo de retención inicia con la respuesta del último derecho de petición recibido en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde agotado su tiempo total, se realiza un muestreo aleatorio así: de 1 a 60 unidades del 10%, de 61 a 200 el 5% y de 201 a N el 2%, por vigencia. La muestra obtenida de la selección se conserva permanentemente por cuanto da testimonio de la gestión institucional en el marco de los derechos de petición tramitado en un determinado tiempo para la historia de la entidad. Para garantizar la disponibilidad y acceso a la información de esta agrupación documental la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan preservación a largo plazo por la entidad, con el fin de atender la consulta y la conformación de la memoria institucional. Los documentos de archivo no seleccionados se eliminan, de conformidad con lo establecido en el procedimiento de disposición final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, articulo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Derecho de petición'), (@id, 2, NULL, 'Respuesta a derecho de petición');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.2', NULL, '42', 'INFORMES', '42.29', 'Informes de Gestión', 'EL', 'IPU', 1, 4, 'El tiempo de retención inicia a partir de la última entrega del informe de gestión en la vigencia.', 'E', 'Subserie documental que permite la consolidación de la información general, donde se da cuenta de los logros, metas y procesos de la gestión en un período determinado. El tiempo de retención inicia a partir de la última entrega del informe de gestión en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, donde, agotado su tiempo total, se elimina, por cuanto la información se consolida en la serie Informes, subserie Informes de Gestión anual Institucional, en la Dirección de Planeación y Direccionamiento Corporativo. La eliminación se realiza atendiendo lo establecido en el procedimiento de Disposición Final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Informe de gestión'), (@id, 2, NULL, 'Comunicación de remisión informe');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.2', 'PROCESO GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '53', 'PLANES', '53.38', 'Planes Institucionales de la oferta Abierta Titulada', 'EL', 'IPU', 2, 8, 'El tiempo de retención inicia con el informe de seguimiento a la oferta educativa del centro de formación.', 'CT', 'Subserie documental que evidencia la estructura y organización de los programas bajo la oferta abierta titulada. Esta modalidad permite a los aspirantes acceder a la oferta según calendario académico institucional, facilitando así el acceso a la formación profesional integral. El tiempo de retención inicia con el informe de seguimiento a la oferta educativa del centro de formación. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto contiene información esencial para asegurar la calidad, la consistencia y la relevancia de la educación técnica y tecnológica ofertada por el SENA. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo-SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Plan de acción de la vigencia'), (@id, 2, NULL, 'Resolución calendario académico'), (@id, 3, NULL, 'Resolución convocatoria de la oferta'), (@id, 4, NULL, 'Reporte de planeación indicativa oferta abierta titulada'), (@id, 5, NULL, 'Acta de planeación de oferta del centro de formación'), (@id, 6, NULL, 'Acta de aprobación de oferta concertada con centro suscrita por el Director Regional o Dirección de Formación Profesional'), (@id, 7, NULL, 'Informe de seguimiento a la oferta educativa del centro de formación');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.2', 'PROCESO GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '53', 'PLANES', '53.39', 'Planes Institucionales de la Oferta Especial Complementaria', 'EL', 'IPU', 2, 8, 'El tiempo de retención inicia con el reporte de verificación de condiciones mínimas de calidad de ambientes de formación.', 'CT', 'Subserie documental que evidencia la formación en áreas específicas que no están completamente cubiertas por los programas regulares del SENA. Pueden incluir cursos cortos, seminarios, talleres intensivos u otros tipos de actividades formativas. El tiempo de retención inicia con el reporte de verificación de condiciones mínimas de calidad de ambientes de formación. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto contiene información que permitió ampliar las habilidades técnicas y tecnológicas en áreas específicas, aumentando así su empleabilidad y capacidad de contribuir de manera efectiva al desarrollo económico y social del país a lo largo del tiempo. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo-SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Plan de acción de la vigencia'), (@id, 2, NULL, 'Registro de solicitudes'), (@id, 3, NULL, 'Acta de compromiso entre la empresa y el SENA'), (@id, 4, NULL, 'Plan operativo de la oferta especial complementaria'), (@id, 5, NULL, 'Reporte de verificación condiciones mínimas de calidad de ambientes de formación');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.2', 'PROCESO GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '53', 'PLANES', '53.40', 'Planes Institucionales de la oferta Especial Titulada', 'EL', 'IPU', 2, 8, 'El tiempo de retención inicia con el informe de análisis de ejecución, certificación y deserción.', 'CT', 'Subserie documental que detalla la estructura, organización y objetivos de los programas de formación especializados ofertados en articulación con la media. El tiempo de retención inicia con el informe de análisis de ejecución, certificación y deserción. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto contiene información histórica de los cambios en las demandas del mercado laboral, avances tecnológicos y nuevas tendencias en los sectores específicos en un periodo determinado. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo- SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Comunicación de solicitud de matricula'), (@id, 2, NULL, 'Reporte de novedades de los ambientes de aprendizaje de formación'), (@id, 3, NULL, 'Comunicación de observaciones a solicitud de matricula'), (@id, 4, NULL, 'Reportes de inscripción y matricula'), (@id, 5, NULL, 'Informe de análisis de ejecución, certificación y deserción');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '02', 'ACTAS', '02.45', 'Actas de Equipo Pedagógico de Centros', 'EL', 'IPU', 2, 8, 'Administrar las actas correspondientes y llevar el archivo de las mismas El tiempo de retención inicia con la última acta de equipo pedagógico de Centros - EPC suscrita en la vigencia.', 'CT', 'Subserie documental que evidencia las decisiones que buscan garantizar la calidad y efectividad de la formación profesional integral, atendiendo lo establecido en la Resolución 184 de 2013, artículo 4. Gestión del Equipo Pedagógico de Centro- Roles. b) secretario literal (a) numeral 5. Administrar las actas correspondientes y llevar el archivo de las mismas El tiempo de retención inicia con la última acta de equipo pedagógico de Centros - EPC suscrita en la vigencia. Cumplido el tiempo de retención en el archivo de gestión se transfiere el soporte original al archivo central en donde agotado su tiempo total se conservan por cuanto contienen información que da testimonio de las decisiones y acciones que garantizaron que los instructores del SENA contaron con el apoyo necesario para desarrollar una educación técnica y profesional de alta calidad, contribuyendo significativamente a mejorar las prácticas pedagógicas y a preparar a los aprendices para enfrentar exitosamente el mercado laboral en un periodo determinado. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas, tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo- SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Acta de equipo pedagógico de centros - EPC');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'RELACIONAMIENTO CON LA CIUDADANÍA, LA EMPRESA Y ACTORES INTERNACIONALES', '27', 'DERECHOS DE PETICIÓN', '', '', 'EL', 'IPU', 1, 9, 'El tiempo de retención inicia con la respuesta del último derecho de petición recibido en la vigencia.', 'S', 'Serie documental que evidencia los derechos de petición que interponen los ciudadanos por cualquiera de los canales de atención dispuestos por la entidad para tal fin. En cumplimiento del artículo 23 de la Constitución Política de Colombia, Ley 1437 de 2011, Ley 1712 de 2014, Ley 1755 de 2015, Resolución 01365 de 2022 SENA y normas y/o actos administrativos que modifiquen adicionen o sustituyan. El tiempo de retención inicia con la respuesta del último derecho de petición recibido en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde agotado su tiempo total, se realiza un muestreo aleatorio así: de 1 a 60 unidades del 10%, de 61 a 200 el 5% y de 201 a N el 2%, por vigencia. La muestra obtenida de la selección se conserva permanentemente por cuanto da testimonio de la gestión institucional en el marco de los derechos de petición tramitado en un determinado tiempo para la historia de la entidad. Para garantizar la disponibilidad y acceso a la información de esta agrupación documental la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan preservación a largo plazo por la entidad, con el fin de atender la consulta y la conformación de la memoria institucional. Los documentos de archivo no seleccionados se eliminan, de conformidad con lo establecido en el procedimiento de disposición final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, articulo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Derecho de Petición'), (@id, 2, NULL, 'Respuesta a Derecho de Petición');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'RELACIONAMIENTO CON LA CIUDADANÍA, LA EMPRESA Y ACTORES INTERNACIONALES', '42', 'INFORMES', '42.29', 'Informes de Gestión', 'EL', 'IPU', 1, 4, 'El tiempo de retención inicia a partir de la última entrega del informe de gestión en la vigencia.', 'E', 'Subserie documental que permite la consolidación de la información general, donde se da cuenta de los logros, metas y procesos de la gestión en un período determinado. El tiempo de retención inicia a partir de la última entrega del informe de gestión en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, donde, agotado su tiempo total, se elimina, por cuanto la información se consolida en la serie Informes, subserie Informes de Gestión anual Institucional, en la Dirección de Planeación y Direccionamiento Corporativo. La eliminación se realiza atendiendo lo establecido en el procedimiento de Disposición Final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Informe de gestión'), (@id, 2, NULL, 'Comunicación de remisión informe');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '28', 'DISEÑO CURRICULAR DE LOS PROGRAMAS DE FORMACIÓN PROFESIONAL INTEGRAL', '', '', 'EL', 'IPR', 1, 9, 'El tiempo de retención inicia con el plan de trabajo para actualización del catálogo de programas de formación.', 'CT', 'Serie documental que evidencia las acciones y resultados del diagnóstico para el diseño, estructuración, gestión e instrumentos de evaluación del proyecto curricular que permite mantener actualizado el catálogo de programas de formación integral que ofrece el SENA a lo largo del tiempo con el fin de ajustarse a las necesidades cambiantes del mercado laboral y a las demandas de los sectores productivos. artículo 11, numeral 8 del Decreto 249 de 2004, Decreto 1330 de 2019, artículo 2.5.3.2.3.2.4. Aspectos curriculares. El tiempo de retención inicia con el plan de trabajo para actualización del catálogo de programas de formación. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto proporciona el registro histórico de los diseños curriculares para la creación de programas de formación, los cuales han evolucionado para adaptarse a los cambios y necesidades de la sociedad colombiana y el sector productivo a lo largo del tiempo. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo- SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Plan de trabajo para actualización del los programas de Formación'), (@id, 2, NULL, 'Acta de designación de responsables'), (@id, 3, NULL, 'Matriz perfil de egreso'), (@id, 4, NULL, 'Acta validación interna perfil de egreso'), (@id, 5, NULL, 'Acta validación externa perfil de egreso'), (@id, 6, NULL, 'Acta de validación definitiva perfil de egreso'), (@id, 7, NULL, 'Matriz perfil de ingreso'), (@id, 8, NULL, 'Diseño curricular'), (@id, 9, NULL, 'Estado del arte de la ocupación'), (@id, 10, NULL, 'Justificación del programa'), (@id, 11, NULL, 'Listas maestras de materiales'), (@id, 12, NULL, 'Acta de verificación técnica del programa de formación'), (@id, 13, NULL, 'Acta verificación metodológica del programa de formación'), (@id, 14, NULL, 'Acta entrega los programas de centro a regional'), (@id, 15, NULL, 'Documento maestro de condiciones de calidad'), (@id, 16, NULL, 'Proyecto formativo'), (@id, 17, NULL, 'Lista de verificación técnica y metodológica del proyecto formativo'), (@id, 18, NULL, 'Matriz Planeación Pedagógica'), (@id, 19, NULL, 'Guías de Aprendizaje'), (@id, 20, NULL, 'Instrumento de Evaluación'), (@id, 21, NULL, 'Revisión técnica y pedagógica del desarrollo curricular');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '81', 'PROCESOS DE VENTA DE PRODUCTOS', '81.01', 'Procesos de Ventas de Productos y Servicios Clientes Externo', 'EL', 'IPC', 2, 8, 'El tiempo de retención inicia a partir del cierre administrativo de la vigencia.', 'E', 'Subserie documental que evidencia el proceso de recaudo de ventas externas de producción por la venta de productos y servicios desarrollados por los aprendices. El tiempo de retención inicia a partir del cierre administrativo de la vigencia. Cumplido el tiempo de retención, en el archivo de gestión se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se elimina, por cuanto la información queda registrada en contabilidad en los pagos de obligaciones. La eliminación se realiza atendiendo lo establecido en el procedimiento de Disposición Final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Catálogo de productos de Centro de Formación'), (@id, 2, NULL, 'Pre factura del valor del articulo centro e identificación'), (@id, 3, NULL, 'Cupón de Pago'), (@id, 4, NULL, 'Facturación electrónica'), (@id, 5, NULL, 'Consignación por venta de baja cuantías');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '81', 'PROCESOS DE VENTA DE PRODUCTOS', '81.02', 'Proceso de Ventas de Productos y Servicios Clientes Internos', 'EL', 'IPC', 1, 4, 'El tiempo de retención inicia a partir del cierre administrativo de la vigencia.', 'E', 'Subserie documental que evidencia el proceso de recaudo de producción por la venta de productos y servicios desarrollados por los aprendices. El tiempo de retención inicia a partir del cierre administrativo de la vigencia. Cumplido el tiempo de retención, en el archivo de gestión se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se elimina, por cuanto la información queda registrada en contabilidad en los pagos de obligaciones. La eliminación se realiza atendiendo lo establecido en el procedimiento de Disposición Final a cargo del Grupo Administración de Documentos y previa autorización del Comité Institucional de Gestión y Desempeño o quien haga sus veces. Los documentos en soporte electrónico se destruyen mediante borrado electrónico seguro, atendiendo lo estipulado en el Decreto 1080 de 2015, CAPÍTULO II Evaluación de documentos de archivo, artículo 2.8.2.2.5.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Correo solicitando información del producto o servicio'), (@id, 2, NULL, 'Solicitud de la cotización'), (@id, 3, NULL, 'Respuesta a la solicitud de la cotización'), (@id, 4, NULL, 'Solicitud de CDP y RP'), (@id, 5, NULL, 'Comunicación de envió de los documentos al centro productor o prestador del servicio'), (@id, 6, NULL, 'Cuenta de cobro'), (@id, 7, NULL, 'Recibo a satisfacción'), (@id, 8, NULL, 'Comunicación de remisión a contabilidad para pago de obligación'), (@id, 9, NULL, 'Consignación por venta de baja cuantías');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '37', 'HISTORIAS ACADÉMICAS', '', '', 'EL', 'IPC', 1, 9, 'El tiempo de retención inicia con la expedición del paz y salvo académico- administrativo.', 'CT', 'Subserie documental que evidencia la información cronológica sobre la vinculación y trayectoria académica presencial, a distancia y virtual de los aprendices en desarrollo legal y reglamentario con la entidad. Esta subserie estará a cargo del Grupo de Administración Educativa, en caso de existir en los respectivos centros de formación. De lo contrario, continuará bajo la responsabilidad del Grupo de Formación Integral, Gestión Educativa y Promoción y Relaciones Corporativas de conformidad con la resolución 928 de 2006. El tiempo de retención inicia con la expedición del paz y salvo académico- administrativo. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conservan permanentemente por cuanto registran información sobre los egresados, incluyendo su edad, género, nivel educativo y ubicación geográfica. Esta información es esencial para analizar las características demográficas de los aprendices que han pasado por el SENA; además, permite mantener un registro histórico y valioso de los sectores productivos regionales y locales y las adaptaciones del mercado laboral. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo- SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, 'Ingreso', 'Documento de identidad vigente'), (@id, 2, 'Ingreso', 'Registro del Sistema de matrícula estudiantil de educación básica y media- SIMAT, (articulación con la media)'), (@id, 3, 'Ingreso', 'Acta de compromiso del aprendiz'), (@id, 4, 'Ingreso', 'Autorización de datos de menor de edad'), (@id, 5, 'Ingreso', 'Documento de identificación del padre, tutor o acudiente'), (@id, 6, 'Ingreso', 'Certificados académicos para el proceso de matricula (salvo regulación especial)'), (@id, 7, 'Ingreso', 'Documento de convalidación de certificados académicos u otros'), (@id, 8, 'Ingreso', 'Certificado de afiliación EPS'), (@id, 9, 'Ingreso', 'Resultado prueba ICFES, saber 11'), (@id, 10, 'Ingreso', 'Registro de asistencia para formalizar matrícula'), (@id, 11, 'Ejecución', 'Constancia de reconocimiento para pensión de sobrevivientes'), (@id, 12, 'Ejecución', 'Llamado de atención escrito académico o disciplinario'), (@id, 13, 'Ejecución', 'Solicitud de novedades (reingreso, aplazamiento, retiro voluntario, traslado y condicionamiento)'), (@id, 14, 'Ejecución', 'Respuesta a solicitud de novedad'), (@id, 15, 'Ejecución', 'Actas de reunión del comité de seguimiento y evaluación de etapa lectiva y/o productiva'), (@id, 16, 'Ejecución', 'Resolución de reingreso, sancionatoria o cancelación matrícula, plan de mejoramiento académico o disciplinario'), (@id, 17, 'Ejecución', 'Solicitud de recurso de reposición'), (@id, 18, 'Ejecución', 'Acto administrativo recurso reposición'), (@id, 19, 'Ejecución', 'Comunicación de presentación etapa practica lectiva'), (@id, 20, 'Ejecución', 'Acta de cierre etapa lectiva'), (@id, 21, 'Ejecución', 'Comunicación selección de etapa productiva'), (@id, 22, 'Ejecución', 'Afiliación al sistema general de riesgos laborales de aprendices - ARL'), (@id, 23, 'Ejecución', 'Registro planeación, seguimiento y evaluación de la etapa productiva'), (@id, 24, 'Ejecución', 'Bitácora de seguimiento etapa productiva'), (@id, 25, 'Ejecución', 'Solicitud de cambio de etapa productiva'), (@id, 26, 'Ejecución', 'Queja o reclamación por el aprendiz del proceso de formación'), (@id, 27, 'Ejecución', 'Certificado de aprobación empresa terminación etapa productiva'), (@id, 28, 'Ejecución', 'Informe de bienestar del aprendiz ruta de atención para la prevención de la deserción'), (@id, 29, 'Certificación', 'Documento de identidad en caso de cambio del mismo'), (@id, 30, 'Certificación', 'Paz y salvo académico administrativo o comunicación de institución educativa'), (@id, 31, 'Certificación', 'Certificado de Inscripción en el aplicativo de la APE'), (@id, 32, 'Certificación', 'Resultados de la prueba saber TyT ante el ICFES para aprendices del nivel tecnológico'), (@id, 33, 'Certificación', 'Constancia de buena conducta'), (@id, 34, 'Certificación', 'Control y expedición y entrega de duplicados (años anteriores al año 2000)'), (@id, 35, 'Certificación', 'Solicitud modificación de documentos académicos con su respectivo soporte'), (@id, 36, 'Certificación', 'Constancia de validación académica para apostillar');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '85', 'PROGRAMAS', '85.16', 'Programas de Formación Presencial y a Distancia', 'EL', 'IPU', 1, 9, 'El tiempo de retención inicia con el informe de aprendices certificados.', 'CT', 'Subserie documental que evidencia las estrategias de los programas ofertados, desarrollados de manera presencial, a distancia y virtual, utilizando diversos recursos que facilitan el proceso formativo de los aprendices. Esta subserie estará a cargo del Grupo de Administración Educativa, en caso de existir en los respectivos centros de formación. De lo contrario, continuará bajo la responsabilidad del Grupo de Formación Integral, Gestión Educativa y Promoción y Relaciones Corporativas. El tiempo de retención inicia con el informe de aprendices certificados. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto contiene información histórica de la incorporación de nuevas tecnologías y metodologías educativas, alineados con las necesidades cambiantes del mercado laboral y las demandas de la sociedad digital. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo- SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Proyecto de viabilidad (articulación con la media)'), (@id, 2, NULL, 'Autodiagnóstico institución educativa (articulación con la media)'), (@id, 3, NULL, 'Notificación novedades ambientes de formación'), (@id, 4, NULL, 'Plan académico o de formación (plan de acción)'), (@id, 5, NULL, 'Acta compromiso con institución educativa'), (@id, 6, NULL, 'Acta de planeación oferta educativa'), (@id, 7, NULL, 'Plan operativo'), (@id, 8, NULL, 'Cronograma charlas informativas'), (@id, 9, NULL, 'Acta de sensibilización articulación con la media'), (@id, 10, NULL, 'Articulación currículo educación media y programa de formación Sena'), (@id, 11, NULL, 'Acta de transferencia técnica y pedagógica'), (@id, 12, NULL, 'Planeación pedagógica'), (@id, 13, NULL, 'Lista de verificación procedimiento ejecución de la formación'), (@id, 14, NULL, 'Reporte de inasistencia'), (@id, 15, NULL, 'Justificación inasistencia'), (@id, 16, NULL, 'Reporte de juicios de evaluación etapa lectiva y productiva'), (@id, 17, NULL, 'Programación de aulas móviles'), (@id, 18, NULL, 'Informe de seguimiento y evaluación del proceso');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÒN DE EMPRENDIMIENTO Y EMPRESARISMO', '85', 'PROGRAMAS', '85.15', 'Programas de Emprendimiento', 'EL', 'IPC', 2, 8, 'El tiempo de retención inicia a partir del cierre de la asesoria en la puesta en marcha o un cierre fortuito.', 'CT', 'Subserie documental que evidencia la fase de entrenamiento, asesoría, transferencia de conocimiento y experiencias sobre un tema relacionado con el emprendimiento, atendiendo lo establecido en los numerales 53 y 74, parágrafo 2 de la Ley 2069 DE 2020. El tiempo de retención inicia a partir del cierre de la asesoria en la puesta en marcha o un cierre fortuito. Cumplido el tiempo de retención, en el archivo de gestión se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto da testimonio de la implementación de programas de entrenamiento de emprendimiento. Los culés promovieron el desarrollo económico, social y tecnológico de un país, fomentando la capacidad emprendedora del país a través de la creación de empleo, innovación y bienestar de la sociedad en un periodo determinado. Para garantizar la disponibilidad y acceso a la información de esta Agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo por la entidad, con el fin de atender la consulta y la conformación de la memoria institucional.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Plan de acción y seguimiento'), (@id, 2, NULL, 'Lista de asistencia a eventos de orientación'), (@id, 3, NULL, 'Lista de asistencia a eventos de entrenamiento');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÒN DE EMPRENDIMIENTO Y EMPRESARISMO', '53', 'PLANES', '53.21', 'Planes de Negocios', 'EL', 'IPU', 1, 9, 'El tiempo de retención inicia a partir del cierre administrativo del plan.', 'CT', 'Subserie documental que evidencia la fase de entrenamiento, asesoría, transferencia de conocimiento y experiencias sobre un tema relacionado con el emprendimiento, atendiendo lo establecido en los numerales 53 y 74, parágrafo 2 de la Ley 2069 DE 2020. El tiempo de retención inicia a partir del cierre administrativo del plan. Cumplido el tiempo de retención, en el archivo de gestión se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto da testimonio de la implementación de programas de entrenamiento de emprendimiento. Los culés promovieron el desarrollo económico, social y tecnológico de un país, fomentando la capacidad emprendedora del país a través de la creación de empleo, innovación y bienestar de la sociedad en un periodo determinado. Para garantizar la disponibilidad y acceso a la información de esta Agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo por la entidad, con el fin de atender la consulta y la conformación de la memoria institucional.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, 'Otras Fuentes de Financiación', 'Plan de negocio de otras fuentes de financiación'), (@id, 2, 'Otras Fuentes de Financiación', 'Cámara de comercio empresa creada'), (@id, 3, 'Otras Fuentes de Financiación', '‎Registro único tributario- RUT empresa establecida'), (@id, 4, 'Otras Fuentes de Financiación', 'Correo electrónico de programación de asesoria puesta en marcha'), (@id, 5, 'Otras Fuentes de Financiación', 'Correo electrónico de cierre Fortuito del servicio de asesoría (si aplica)'), (@id, 6, 'Otras Fuentes de Financiación', 'Correo electrónico de cierre de servicio de asesoría'), (@id, 7, 'Fondo Emprender', 'Matriz de valoración del modelo de negocio'), (@id, 8, 'Fondo Emprender', 'Plan de negocio fondo emprender'), (@id, 9, 'Fondo Emprender', 'Cámara de comercio empresa creada'), (@id, 10, 'Fondo Emprender', '‎Registro único tributario- RUT empresa establecida'), (@id, 11, 'Fondo Emprender', 'Acta de seguimiento técnico - operativa'), (@id, 12, 'Fondo Emprender', 'Actas de interventoría'), (@id, 13, 'Fondo Emprender', 'Correo electrónico de cierre Fortuito del servicio de asesoría (si aplica)'), (@id, 14, 'Fondo Emprender', 'Correo electrónico de cierre de servicio de asesoría'), (@id, 15, 'Fortalecimiento Empresarial', 'Cámara de comercio empresa creada'), (@id, 16, 'Fortalecimiento Empresarial', '‎Registro único tributario- RUT empresa establecida'), (@id, 17, 'Fortalecimiento Empresarial', 'Plan de acción de fortalecimiento empresarial'), (@id, 18, 'Fortalecimiento Empresarial', 'Correo electrónico de cierre Fortuito del servicio de asesoría (si aplica)'), (@id, 19, 'Fortalecimiento Empresarial', 'Correo electrónico de cierre de servicio de asesoría');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '53', 'PLANES', '53.07', 'Planes de Acción de Bienestar al Aprendiz', 'EL', 'IPU', 1, 9, 'El tiempo de retención inicia a partir de la pérdida de la vigencia.', 'CT', 'Subserie documental que evidencia los lineamientos, acciones y estrategia institucional para contribuir en la permanencia y el desempeño exitoso de los aprendices de la entidad en su proceso formativo con enfoque territorial y diferencial. Atendiendo lo establecido en el Acuerdo 8 DE 1997 SENA. y el Decreto 1330 del 2019 en el artículo 2.5.3.2.3.1.6. El tiempo de retención inicia a partir de la pérdida de la vigencia. Cumplido el tiempo de retención, en el archivo de gestión se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conservará permanentemente, por cuanto da testimonio de las estrategias que permitieron el desarrollo integral del aprendiz en su proceso formativo. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo- SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Plan de acción de bienestar del aprendiz'), (@id, 2, NULL, 'Acta de elección de representante o vocero'), (@id, 3, NULL, 'Acta de aprobación del PBCF'), (@id, 4, NULL, 'Plan de mejoramiento');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '85', 'PROGRAMAS', '85.04', 'Programas de Apoyos de Sostenimiento Regular', 'EL', 'IPU', 1, 4, 'El tiempo de retención inicia a partir del cierre de la vigencia.', 'CT', 'Subserie documental que evidencia la asignación de apoyos regulares, apoyos económicos proporcionados a los aprendices con el fin de ayudarles a cubrir los gastos relacionados con su formación y manutención durante su participación formativa. Atendiendo lo establecido en la Resolución 169 de 2022. El tiempo de retención inicia a partir del cierre de la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto guarda relación con la misión de la entidad, toda vez que apoyos socioeconómicos como estrategia contribuyeron en un periodo determinado al logro de los objetivos de ofrecer educación técnica y tecnológica de calidad, equitativa y accesible para todos los colombianos. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo- SGDEA.');
