INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '85', 'PROGRAMAS', '85.07', 'Programas de Apoyos Socioeconómicos Medios Tecnológicos', 'EL', 'IPU', 1, 4, 'El tiempo de retención inicia a partir del cierre de la vigencia.', 'CT', 'Subserie documental que evidencia la asignación de apoyos de sostenimiento de medios tecnológicos mediante transferencia bancaria al aprendiz para apalancar el pago mensual de gastos (plan de datos como medio para la formación tecnológica en la etapa lectiva o productiva); orientando a todos los aprendices de las modalidades y niveles que se encuentren en ambientes de aprendizaje y escenarios formativos donde se desarrolle la ejecución de la formación. Su asignación será previo cumplimiento de requisitos, atendiendo lo establecido en el Acuerdo 8 de 2009, Resolución 169 de 2022. El tiempo de retención inicia a partir del cierre de la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto guarda relación con la misión de la entidad, toda vez que apoyos socioeconómicos como estrategia contribuyeron en un periodo determinado al logro de los objetivos de ofrecer educación técnica y tecnológica de calidad, equitativa y accesible para todos los colombianos. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo por la entidad, con el fin de atender la consulta y la conformación de la memoria institucional.');
