INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '85', 'PROGRAMAS', '85.08', 'Programas de Asignación Cupos Internados - Centros de Convivencia', 'EL', 'IPU', 1, 4, 'El tiempo de retención inicia a partir del cierre de la vigencia.', 'CT', 'Subserie documental que evidencia la promoción y gestión socioeconómica de la entidad a partir del servicio de internado, la cual contribuye a la permanencia y el desarrollo integral del aprendiz en su proyecto formativo por circunstancias geográficas, falta de medio de transporte o la distancia al centro de formación, entre otras, que hacen complejo el acceso a la formación, atendiendo lo establecido en el Acuerdo 8 de 2009, Resolución 169 de 2022. El tiempo de retención inicia a partir del cierre de la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto guarda relación con la misión de la entidad, toda vez que apoyos socioeconómicos como estrategia contribuyeron en un periodo determinado al logro de los objetivos de ofrecer educación técnica y tecnológica de calidad, equitativa y accesible para todos los colombianos. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo por la entidad, con el fin de atender la consulta y la conformación de la memoria institucional.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Acta de evidencia de divulgación de la convocatoria'), (@id, 2, NULL, 'Circular de apertura convocatoria'), (@id, 3, NULL, 'Trazabilidad de aprendices beneficiarios centros de convivencia'), (@id, 4, NULL, 'Acta de desempate'), (@id, 5, NULL, 'Resolución de adjudicación'), (@id, 6, NULL, 'Resolución de cancelación o suspensión'), (@id, 7, NULL, 'Legalización de ingreso al internado');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '85', 'PROGRAMAS', '85.09', 'Programas de Asignación de Monitorias por Excelencia', 'EL', 'IPU', 1, 4, 'El tiempo de retención inicia a partir del cierre de la vigencia.', 'CT', 'Subserie documental que evidencia el conjunto de actividades mediante las cuales los aprendices seleccionados apoyan los procesos de formación a través de acciones complementarias para garantizar mayores niveles de calidad en todos los elementos que contribuyen al proceso formativo, atendiendo lo establecido en la circular 34 de 2023. El tiempo de retención inicia a partir del cierre de la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto guarda relación con la misión de la entidad, toda vez que es una estrategia educativa que implica la asignación de monitores que brindaron apoyo adicional a los aprendices en su proceso de formación, mejorando la calidad de la formación y el rendimiento académico de los aprendices. Para garantizar la disponibilidad y acceso a la información de esta Agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo por la entidad, con el fin de atender la consulta y la conformación de la memoria institucional.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Circular de apertura convocatoria'), (@id, 2, NULL, 'Informe verificación de requisitos'), (@id, 3, NULL, 'Acta de desempate'), (@id, 4, NULL, 'Resolución de adjudicación'), (@id, 5, NULL, 'Resolución de cancelación o suspensión'), (@id, 6, NULL, 'Informe de evaluación');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '86', 'PROGRAMAS DE APOYOS DE SOSTENIMIENTO', '86.01', 'Programa de Apoyos de Sostenimiento Fondo Nacional de la Industria de la Construcción - FIC', 'EL', 'IPU', 1, 4, 'El tiempo de retención inicia a partir del cierre de la vigencia.', 'CT', 'Subserie documental que evidencia la asignación de recursos equivalentes al sesenta (60%) del salario mínimo mensual vigente SMLMV otorgado a los aprendices que reciben formación profesional integral, que guardan relación con los diferentes oficios y ocupaciones de la industria de la construcción con el objetivo de sufragar gastos básicos en los que incurre un aprendiz en el proceso formativo. Estos apoyos están diseñados para mitigar la deserción por las barreras económicas que algunos aprendices pueden enfrentar y así fomentar su participación y éxito en los programas de formación. Atendiendo lo establecido en la Resolución 2140 de 2021 o las normas que la modifiquen. El tiempo de retención inicia a partir del cierre de la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto guarda relación con la misión de la entidad, toda vez que apoyos socioeconómicos a partir de la estrategia contribuyeron en un periodo determinado al logro de los objetivos de ofrecer educación técnica y tecnológica de calidad, equitativa y accesible para todos los colombianos. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo por la entidad, con el fin de atender la consulta y la conformación de la memoria institucional.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Circular de apertura convocatoria'), (@id, 2, NULL, 'Acta de evidencia de divulgación dcon registro de evidencia'), (@id, 3, NULL, 'Reporte de inscritos'), (@id, 4, NULL, 'Reporte de priorización de elegibles'), (@id, 5, NULL, 'Listado de elegibles'), (@id, 6, NULL, 'Acta de desempate'), (@id, 7, NULL, 'Acta del encuentro de socialización de aprendices beneficiados'), (@id, 8, NULL, 'Resolución adjudicación'), (@id, 9, NULL, 'Resolución cancelación o suspensión'), (@id, 10, NULL, 'Resolución y reporte de desembolso mensuales'), (@id, 11, NULL, 'Registro socioeconómico'), (@id, 12, NULL, 'Acta de seguimiento mensual de verificación de cumplimiento de requisitos y obligaciones');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE INSTANCIAS DE CONCERTACIÓN Y COMPETENCIAS LABORALES', '02', 'ACTAS', '02.42', 'Actas de Consejos Ejecutivo de Mesas Sectoriales', 'EL', 'IPC', 1, 9, 'El tiempo de retención inicia a partir de la última acta precedida en la vigencia.', 'CT', 'Subserie documental que evidencia las decisiones en torno a iniciativas que propendan por un desarrollo integral del talento humano del sector y que estimulen la conformación de alianzas estratégicas, a nivel nacional e internacional, con el fin de compartir avances tecnológicos, atendiendo lo establecido en los artículos 14 y 22 literal (b) del Acuerdo 0003 de 2018 SENA. El tiempo de retención inicia a partir de la última acta precedida en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto proporcionan un registro histórico de las decisiones, discusiones y acciones tomadas en reuniones clave. Estos registros son valiosos para rastrear la evolución de las políticas, estrategias y enfoques a lo largo del tiempo de la entidad. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo-SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Acta de consejo ejecutivo de mesa sectorial');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE INSTANCIAS DE CONCERTACIÓN Y COMPETENCIAS LABORALES', '02', 'ACTAS', '02.54', 'Actas de Reunión de Mesas Sectoriales', 'EL', 'IPC', 1, 9, 'El tiempo de retención inicia a partir de la última acta precedidas en la vigencia.', 'CT', 'Subserie documental que evidencia las decisiones en torno a la concertación, donde se proponen políticas para la formación, mediante la normalización y la certificación de competencias laborales, Atendiendo lo establecido en el artículo 12 del Acuerdo 0003 de 2018 SENA. El tiempo de retención inicia a partir de la última acta precedidas en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde agotado su tiempo total, se conserva por cuanto proporcionan un registro histórico de las decisiones, discusiones y acciones tomadas por lo miembros de este comité. Estos registros son valiosos para rastrear la evolución de las políticas, estrategias y enfoques a lo largo del tiempo. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas, tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo- SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Acta de reunión mesa sectorial');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE INSTANCIAS DE CONCERTACIÓN Y COMPETENCIAS LABORALES', '31', 'ESTRUCTURAS FUNCIONALES DE LA OCUPACIÓN', '', '', 'EL', 'IPC', 2, 3, 'El tiempo de retención inicia a partir de la actualización o la inactivación de producto de norma de competencia laboral.', 'CT', 'Serie documental misional que evidencia el conjunto de normas sectoriales de competencia laboral que permiten el logro del propósito de una ocupación. En ella se describe lo que se hace en una ocupación, en qué tipo de organizaciones o sectores se desempeña el trabajador, el nivel de cualificación y las funciones laborales que se desarrollan en la misma. Corresponde a una ocupación e incluye las denominaciones o empleos y las funciones que se desempeñan en ellas. El tiempo de retención inicia a partir de la actualización o la inactivación de producto de norma de competencia laboral. Cumplido el tiempo de retención, en el archivo de gestión se transfiere el soporte original al archivo central donde, agotado su tiempo total, se conserva por cuanto proporciona un registro histórico de los productos de estandarización y normalización, además de ser insumos o referentes para los grupos de valor internos y externos en la elaboración de diseños curriculares o programas de formación, procesos de evaluación y certificación, diseño de cualificaciones y talento humano, entre otros. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo-SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Identificación de perfil consecución expertos técnicos'), (@id, 2, NULL, 'Solicitud consecución expertos técnicos'), (@id, 3, NULL, 'Invitación a confirmación comité técnico'), (@id, 4, NULL, 'Matriz fuente de información de investigación sectorial'), (@id, 5, NULL, 'Matriz análisis crítico de la información'), (@id, 6, NULL, 'Actas de comités técnicos de elaboración / actualización de EFO'), (@id, 7, NULL, 'Estructura funcional de la ocupación -EFO'), (@id, 8, NULL, 'Ficha de caracterización del comité técnico de elaboración / actualización estructura funcional de la ocupación -EFO'), (@id, 9, NULL, 'Lista de ajuste verificación metodológica'), (@id, 10, NULL, 'Actas de comités validación técnica'), (@id, 11, NULL, 'Formatos validación técnica'), (@id, 12, NULL, 'Ficha de caracterización comité de validación técnica normalización/ estandarización'), (@id, 13, NULL, 'Lista de ajuste verificación metodológica pos validación técnica'), (@id, 14, NULL, 'Acta Aval Consejo Ejecutivo Mesa Sectorial'), (@id, 15, NULL, 'Respuesta a encuesta grupos de valor realimentación de la norma en uso');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE INSTANCIAS DE CONCERTACIÓN Y COMPETENCIAS LABORALES', '49', 'MAPAS FUNCIONALES', '', '', 'EL', 'IPC', 2, 3, 'El tiempo de retención inicia a partir del último reporte del estado de conformidad de producto frente a verificación metodológica o validación técnica en la vigencia.', 'CT', 'Serie documental misional que describe la razón de ser de la actividad productiva de un sector o área objeto de análisis. El mapa funcional es un diagrama resultado del análisis funcional en el que se relacionan únicamente las funciones misionales del sector o área de análisis sin definir quién las hace, cómo se hacen o el tipo de tecnología o maquinaria que se utiliza. El tiempo de retención inicia a partir del último reporte del estado de conformidad de producto frente a verificación metodológica o validación técnica en la vigencia. Cumplido el tiempo de retención, en el archivo de gestión se transfiere el soporte original al archivo central, donde, agotado su tiempo total, se conserva, por cuanto es el punto de partida que soporta la normalización/estandarización de competencias laborales. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo-SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Solicitud consecución expertos técnicos'), (@id, 2, NULL, 'Invitación a conformación comité técnico'), (@id, 3, NULL, 'Actas de comités técnicos de elaboración / actualización de mapa funcional'), (@id, 4, NULL, 'Ficha de caracterización del comité técnico de elaboración / actualización mapa funcional'), (@id, 5, NULL, 'Lista de Ajuste Verificación Metodológica'), (@id, 6, NULL, 'Actas de comités validación técnica'), (@id, 7, NULL, 'Validación técnica'), (@id, 8, NULL, 'Ficha de caracterización comité de validación técnica mapa funcional'), (@id, 9, NULL, 'Listas de ajuste verificación metodológica pos validación técnica'), (@id, 10, NULL, 'Acta aval consejo ejecutivo mesa sectorial');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE INSTANCIAS DE CONCERTACIÓN Y COMPETENCIAS LABORALES', '51', 'NORMAS DE COMPETENCIAS LABORALES', '', '', 'EL', 'IPU', 1, 4, 'El tiempo de retención inicia a partir de la actualización o la inactivación del producto norma de competencias laborales.', 'CT', 'Serie documental misional que evidencia el estándar nacional reconocido como satisfactorio y aplicable a todas las organizaciones productivas del área objeto de análisis. Es el resultado de someter la Unidad de Competencia Laboral a un proceso de consulta pública con el sector productivo respectivo. Se trata de documentos técnicos que especifican los requisitos mínimos necesarios para desempeñar un trabajo de manera eficiente y eficaz. Estos documentos son el resultado de un proceso de investigación y análisis de las competencias requeridas en diferentes oficios y profesiones, y están diseñados para garantizar la calidad y pertinencia de la formación y capacitación que ofrece el SENA. Atendiendo lo establecido en el artículo 12 del Decreto 249 del 2004 y el Decreto 945 del 2022. El tiempo de retención inicia a partir de la actualización o la inactivación del producto norma de competencias laborales. Cumplido el tiempo de retención, en el archivo de gestión se transfiere el soporte original al archivo central donde, agotado su tiempo total, se conserva por cuanto proporciona un registro histórico de los productos de estandarización y normalización, pues son insumos o referentes para los grupos de valor internos y externos en la elaboración de diseños curriculares o programas de formación, procesos de evaluación y certificación, diseño de cualificaciones y talento humano. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo- SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Identificación de perfil consecución expertos técnico'), (@id, 2, NULL, 'Solicitud consecución expertos técnico'), (@id, 3, NULL, 'Invitación a confirmación comité técnico'), (@id, 4, NULL, 'Matriz fuente de información de investigación sectorial'), (@id, 5, NULL, 'Matriz análisis crítico de la información'), (@id, 6, NULL, 'Actas de comités técnicos de elaboración actualización de normalización y estandarización'), (@id, 7, NULL, 'Estructura de estándar /norma sectorial de competencia laborales'), (@id, 8, NULL, 'Matriz Correlación de Desempeño Laboral'), (@id, 9, NULL, 'Estructura funcional de la ocupación -EFO estándar /norma sectorial de competencia laborales'), (@id, 10, NULL, 'Ficha de caracterización del comité técnico de elaboración / actualización de normalización/ estandarización'), (@id, 11, NULL, 'Solicitud de acompañamientos metodológico'), (@id, 12, NULL, 'Lista de verificación metodológica'), (@id, 13, NULL, 'Solicitud consulta pública'), (@id, 14, NULL, 'E-card divulgación consulta Pública'), (@id, 15, NULL, 'Estructura de estándar /norma sectorial de competencia laboral'), (@id, 16, NULL, 'Invitación a participar en consulta pública'), (@id, 17, NULL, 'Reporte de observaciones de expertos técnicos'), (@id, 18, NULL, 'Informe de comentarios de expertos técnicos a norma estándar'), (@id, 19, NULL, 'Actas de comités validación técnica'), (@id, 20, NULL, 'Formatos validación técnica'), (@id, 21, NULL, 'Ficha de caracterización comité de validación técnica normalización/ estandarización'), (@id, 22, NULL, 'Lista de verificación metodológica post validación'), (@id, 23, NULL, 'Carta de presidente de mesa sectorial de presentación de producto'), (@id, 24, NULL, 'Acta aval consejo ejecutivo mesa sectorial'), (@id, 25, NULL, 'Solicitud de presentación de estándar /norma sectorial de competencia laboral a consejo directivo nacional SENA'), (@id, 26, NULL, 'Norma de competencia laboral'), (@id, 27, NULL, 'Respuesta a encuesta grupos de valor realimentación de la norma en uso');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE INSTANCIAS DE CONCERTACIÓN Y COMPETENCIAS LABORALES', '53', 'PLANES', '53.08', 'Planes de Acción de Mesas Sectoriales', 'EL', 'IPU', 1, 9, 'El tiempo de retención inicia a partir del informe de evaluación de gestión del plan Acción de la mesa sectorial en la vigencia.', 'CT', 'Subserie documental que evidencia la gestión y fortalecimiento para la articulación. Interna con el secretario técnico, facilitadores, profesionales de instancias, metodólogos, dinamizadores e integrantes del Consejo Ejecutivo y a nivel externo con planes locales de desarrollo sectoriales, informes elaborados por los entes gubernamentales, de Comisiones Regionales de Competitividad e Innovación. Atendimiento de lo establecido en el Acuerdo 0003 del 2018 en el artículo 19, literales (a y b), artículo 20, literales (b y c) y artículo 22, literales (c, e y g). El tiempo de retención inicia a partir del informe de evaluación de gestión del plan Acción de la mesa sectorial en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto proporciona información. Es esencial que garantice el seguimiento, la ejecución efectiva, la responsabilidad y el cumplimiento de los objetivos sectoriales. Además, permite la evaluación, el aprendizaje y la mejora continua en la gestión de las actividades de la Mesa Sectorial y la consecución de metas futuras de la entidad. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo- SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Plan acción de la mesa sectorial'), (@id, 2, NULL, 'Matriz de seguimiento a la gestión al plan acción de la mesa sectorial'), (@id, 3, NULL, 'Informe de evaluación de gestión del plan acción de la mesa sectorial');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE INSTANCIAS DE CONCERTACIÓN Y COMPETENCIAS LABORALES', '87', 'PROYECTOS', '87.02', 'Proyectos Anual de Competencias Laborales', 'EL', 'IPU', 2, 8, 'El tiempo de retención inicia a partir de la última respuesta a informes de seguimientos y avances del PA en la vigencia.', 'CT', 'Subserie documental que evidencia la misionalidad de la entidad, a partir de identificación y relación de los productos de normalización/estandarización de competencias laborales a elaborar y/o actualizarse en la vigencia, el cual contempla: nombre del producto, responsable, código, estado, caracterización del sector, red de conocimiento, área de cualificación, entre otros. En cumplimiento del artículo 12 del Decreto 249 del 2004 y del Decreto 945 del 2022 del Subsistema Nacional de Normalización. El tiempo de retención inicia a partir de la última respuesta a informes de seguimientos y avances del PA en la vigencia. Cumplido el tiempo de retención, en el archivo de gestión se transfiere el soporte original al archivo central, en donde agota su tiempo 5 años después de la vigencia del proyecto. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo- SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Requerimiento de necesidades de estandarización / normalización'), (@id, 2, NULL, 'Solicitud de requerimiento e necesidades de estandarización / normalización'), (@id, 3, NULL, 'Acta de aprobación del PAE consejo ejecutivo'), (@id, 4, NULL, 'Proyecto anual de estandarización preliminar de competencias laborales -PAE'), (@id, 5, NULL, 'Comunicación concertación PAE centros de formación'), (@id, 6, NULL, 'Respuesta de comunicación concertación PAE centros de formación'), (@id, 7, NULL, 'Proyecto anual de estandarización de competencias laborales definitivo'), (@id, 8, NULL, 'Solicitudes y respuestas a novedades del PAE'), (@id, 9, NULL, 'Respuesta a informes de seguimientos y avances del PAE');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE INSTANCIAS DE CONCERTACIÓN Y COMPETENCIAS LABORALES', '02', 'ACTAS', '02.14', 'Actas de Comité de Gestión de Evaluación y Certificación de Competencias Laborales', 'EL', 'IPC', 1, 9, 'El tiempo de retención inicia con la última acta del comité de gestión de evaluación y certificación de competencias laborales suscrita en la vigencia.', 'CT', 'Subserie documental que evidencia las decisiones frente a la asesoría e implementación de los criterios de calidad en el proceso de evaluación y certificación de competencias laborales del SENA, EN relación con los escenarios de concertación entre los trabajadores y la entidad. En cumplimiento de lo establecido en la ley 909 de 2004, el Decreto 1228 de 2005 y el artículo 2.2.18.8.1 del Decreto 1083 de 2015, Resolución 1352 de 2018, artículo 7. El tiempo de retención inicia con la última acta del comité de gestión de evaluación y certificación de competencias laborales suscrita en la vigencia. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto contiene información que da testimonio de las decisiones y acciones realizadas por este comité referente a la misionalidad en el proceso de evaluación y certificación de competencias laborales. Para garantizar la disponibilidad y acceso a la información de esta Agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo por la entidad, con el fin de atender la consulta y la conformación de la memoria institucional.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Acta comité de gestión de evaluación y certificación de competencias laborales');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE EVALUACIÓN Y CERTIFICACIÓN DE COMPETENCIAS LABORALES', '77', 'PROCESOS DE EVALUACIÓN Y CERTIFICACIÓN DE COMPETENCIAS LABORALES', '', '', 'EL', 'IPC', 2, 8, 'El tiempo de retención inicia con el informe de verificación del grupo de cada proceso.', 'CT', 'Serie documental que evidencia las actividades para la creación, acompañamiento y cierre de proyectos nacionales con agremiaciones, empresas o entidades públicas relacionados con el proceso de evaluación y certificación de competencias laborales. El tiempo de retención inicia con el informe de verificación del grupo de cada proceso. Cumplido el tiempo de retención en el archivo de gestión, se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto contiene información que da testimonio de los acuerdos de agremiaciones, empresas o entidades públicas que benefician a un sector económico determinado. Para garantizar la disponibilidad y acceso a la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta las estrategias establecidas en el plan de preservación a largo plazo por la entidad, con el fin de atender la consulta y la conformación de la memoria institucional.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Acuerdo de confidencialidad de los actores del proceso de ECCL'), (@id, 2, NULL, 'Declaración juramentada de la no existencia de conflicto de interés'), (@id, 3, NULL, 'Solicitud del servicio por línea organización'), (@id, 4, NULL, 'Respuesta del servicio por línea organización'), (@id, 5, NULL, 'Acta de compromiso al proceso de evaluación certificación de competencias laborales por línea organización'), (@id, 6, NULL, 'Cronograma del grupo'), (@id, 7, NULL, 'Lista de asistencia inducción a los candidatos'), (@id, 8, NULL, 'Copia de documento de identidad del candidato'), (@id, 9, NULL, 'Certificación laboral del candidato o plantilla modelo de constancia de experiencia laboral o resultado de fase diagnostica'), (@id, 10, NULL, 'Soportes de requisitos adicionales'), (@id, 11, NULL, 'Aceptación términos y condiciones para candidatos'), (@id, 12, NULL, 'Reporte de inscritos'), (@id, 13, NULL, 'Clave de respuesta de valoración de conocimiento'), (@id, 14, NULL, 'Acta de criterios de desempeño critico / ambiente simulado'), (@id, 15, NULL, 'Hoja de respuesta de valoración de conocimiento'), (@id, 16, NULL, 'Reporte de valoraciones candidato'), (@id, 17, NULL, 'Reporte candidatos evidencias'), (@id, 18, NULL, 'Comunicación de novedades del candidato'), (@id, 19, NULL, 'Comunicación de novedades del proyecto'), (@id, 20, NULL, 'Plan de verificación'), (@id, 21, NULL, 'Acta de apertura de verificación del proyecto'), (@id, 22, NULL, 'Acta de cierre de verificación del proyecto'), (@id, 23, NULL, 'Plan de acción para el tratamiento de acciones correctivas verificación de proyecto'), (@id, 24, NULL, 'Informe de verificación del proyecto');
INSERT INTO trd_registros (version, plantilla, proceso, codigo_serie, nombre_serie, codigo_subserie, nombre_subserie, soporte, clasificacion, retencion_ag, retencion_ac, inicio_retencion, disposicion, procedimiento) VALUES ('11', '00.9000.4', 'GESTIÓN DE FORMACIÓN PROFESIONAL INTEGRAL', '87', 'PROYECTOS', '87.05', 'Proyectos de Investigación, Innovación y Divulgación - SENNOVA', 'EL', 'IPU', 1, 9, 'El tiempo de retención inicia con la suscripción del acta de cierre del proyecto.', 'CT', 'Subserie documental que evidencia las iniciativas específicas que buscan fomentar el desarrollo y la aplicación de conocimientos en áreas relevantes para el SENA y sus programas de formación. Estos proyectos pueden abordar una variedad de temas, desde mejoras en los procesos de enseñanza y aprendizaje hasta la innovación en tecnologías específicas. El tiempo de retención inicia con la suscripción del acta de cierre del proyecto. Cumplido el tiempo de retención, en el archivo de gestión se transfiere el soporte original al archivo central, en donde, agotado su tiempo total, se conserva por cuanto son parte del registro histórico de las iniciativas de investigación e innovación llevadas a cabo por el SENA. Estos proyectos permiten que la institución continúe evolucionando, aprendiendo de sus experiencias y contribuyendo al avance de la investigación, la ciencia y la cultura en el ámbito de la formación técnica y tecnológica. Para garantizar la disponibilidad, integridad y acceso de la información de esta agrupación, la Oficina de Sistemas tendrá en cuenta el plan de preservación digital a largo plazo adoptado por la entidad, especialmente las estrategias relacionadas con copias de seguridad del Sistema de Gestión de Documentos Electrónicos de Archivo- SGDEA.');
INSERT INTO trd_tipos_documentales (trd_id, orden, grupo, nombre) VALUES (@id, 1, NULL, 'Formulación del Proyecto'), (@id, 2, NULL, 'Proyecto de investigación'), (@id, 3, NULL, 'Comunicación de aprobación de proyecto'), (@id, 4, NULL, 'Acta de inicio del proyecto'), (@id, 5, NULL, 'Acta de confidencialidad'), (@id, 6, NULL, 'Actas de seguimiento'), (@id, 7, NULL, 'Matriz de seguimiento marco logico'), (@id, 8, NULL, 'Informe de seguimiento técnico'), (@id, 9, NULL, 'Informe de ejecución presupuestal'), (@id, 10, NULL, '(ponecias, reportes, manuales cartillas diarios de campo articulos cientificos)'), (@id, 11, NULL, 'Registro de propiedad intelectual'), (@id, 12, NULL, 'Informe final del proyecto'), (@id, 13, NULL, 'Acta de cierre del proyecto');
